window.MATERI_DECKS = {"magnetic-fields":{"title":"Magnetic Fields and Electromagnetism","fonts":["https://fonts.googleapis.com/css2?family=Newsreader:ital,opsz,wght@0,6..72,300..600;1,6..72,300..600&display=swap","https://fonts.googleapis.com/css2?family=Public+Sans:wght@400;600;700&display=swap","https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&display=swap"],"sections":[{"key":"s1","start":"cover","description":"Meeting 1: the magnetic field as a field of force, field lines and field patterns","label":{"id":"Pertemuan 1","en":"Meeting 1"}},{"key":"s2","start":"m2","description":"Meeting 2: force on a current-carrying conductor, defining and measuring B","label":{"id":"Pertemuan 2","en":"Meeting 2"}},{"key":"s3","start":"m3","description":"Meeting 3: fields due to currents and forces between conductors","label":{"id":"Pertemuan 3","en":"Meeting 3"}},{"key":"s4","start":"mcq","description":"Practice questions with worked answers and summary","label":{"id":"Latihan & Ringkasan","en":"Practice & Summary"}}],"slides":[{"id":"cover","title":"Magnetic Fields and Electromagnetism","notes":"Open by asking: a compass needle is a tiny magnet, so what is it actually responding to? Over three meetings we build the answer: magnetic fields come from moving charge, they push on moving charge, and two currents push on each other.","html":"<section id=\"cover\" data-transition=\"fade\" style=\"background:#1E1F1C;color:#F1EEE6;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 112px;display:flex;flex-direction:column;justify-content:space-between\">\n<svg aria-label=\"Field rings around a current, spaced further apart with distance\" width=\"740\" height=\"920\" viewBox=\"0 0 740 920\" style=\"position:absolute;left:1180px;top:80px;width:740px;height:920px\"><g fill=\"none\" stroke=\"#7FB5BA\" stroke-width=\"1.5\"><circle cx=\"430\" cy=\"460\" r=\"44\" opacity=\"0.9\"/><circle cx=\"430\" cy=\"460\" r=\"62\" opacity=\"0.85\"/><circle cx=\"430\" cy=\"460\" r=\"87\" opacity=\"0.75\"/><circle cx=\"430\" cy=\"460\" r=\"122\" opacity=\"0.65\"/><circle cx=\"430\" cy=\"460\" r=\"171\" opacity=\"0.55\"/><circle cx=\"430\" cy=\"460\" r=\"239\" opacity=\"0.45\"/><circle cx=\"430\" cy=\"460\" r=\"335\" opacity=\"0.35\"/><circle cx=\"430\" cy=\"460\" r=\"469\" opacity=\"0.25\"/></g><g fill=\"#7FB5BA\"><path d=\"M420 398 l14 -7 l0 14 z\"/><path d=\"M440 582 l-14 -7 l0 14 z\"/><path d=\"M259 470 l-7 -14 l14 0 z\"/><path d=\"M95 450 l-7 14 l14 0 z\" opacity=\"0.6\"/></g><circle cx=\"430\" cy=\"460\" r=\"18\" fill=\"#1E1F1C\" stroke=\"#E9846E\" stroke-width=\"3\"/><circle cx=\"430\" cy=\"460\" r=\"5\" fill=\"#E9846E\"/></svg>\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:2px;color:#BDB8AC\">CAMBRIDGE INTERNATIONAL AS &amp; A LEVEL PHYSICS 9702</p>\n<div style=\"display:flex;flex-direction:column;gap:32px\">\n<h1 style=\"font-family:'Newsreader', Georgia, serif;font-size:112px;font-weight:400;line-height:1.02;letter-spacing:-2px;color:#F1EEE6;width:1150px\">Magnetic Fields <span style=\"color:#E9846E\"><i>and</i></span> Electromagnetism</h1>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px;line-height:1.35;color:#BDB8AC;width:960px\"><i>Fields of force from moving charge, the force on a current, and the forces between currents.</i></p>\n</div>\n<div style=\"display:flex;gap:0px;width:1000px;border-top:1px solid #6F6C64\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:6px;padding:20px 0px 0px 0px\"><p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#9A958A\">TOPIC</p><p style=\"font-size:28px;color:#F1EEE6\">24</p></div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:6px;padding:20px 0px 0px 0px\"><p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#9A958A\">SEQUENCE</p><p style=\"font-size:28px;color:#F1EEE6\">3 meetings</p></div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:6px;padding:20px 0px 0px 0px\"><p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#9A958A\">LEVEL</p><p style=\"font-size:28px;color:#F1EEE6\">Advanced</p></div>\n</div>\n\n</section>"},{"id":"roadmap","title":"Three meetings, one idea: moving charge","notes":"Share the outcomes and tell students the thread that links all three meetings: every magnetic effect here comes back to charge in motion. Practice questions with worked answers are at the end of the deck.","html":"<section id=\"roadmap\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:48px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">Learning outcomes</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Three meetings, one idea: <i>moving charge</i></h2>\n</div>\n<div style=\"display:flex;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:18px;padding:0px 40px 0px 0px;border-right:1px solid #BDB8AC\">\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:120px;font-weight:300;line-height:1;color:#1F6F78\">01</p>\n<h3 style=\"font-family:'Newsreader', Georgia, serif;font-size:38px;font-weight:500;line-height:1.2\">Concept of a magnetic field</h3>\n<p style=\"font-size:25px;line-height:1.5;color:#4A4842\">Describe a magnetic field as a field of force from moving charges or permanent magnets. Use field lines to represent a field and sketch patterns.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:18px;padding:0px 40px 0px 40px;border-right:1px solid #BDB8AC\">\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:120px;font-weight:300;line-height:1;color:#B8391F\">02</p>\n<h3 style=\"font-family:'Newsreader', Georgia, serif;font-size:38px;font-weight:500;line-height:1.2\">Force on a current-carrying conductor</h3>\n<p style=\"font-size:25px;line-height:1.5;color:#4A4842\">Determine the size and direction of the force. Define magnetic flux density and know how it can be measured.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:18px;padding:0px 0px 0px 40px\">\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:120px;font-weight:300;line-height:1;color:#1D1D1B\">03</p>\n<h3 style=\"font-family:'Newsreader', Georgia, serif;font-size:38px;font-weight:500;line-height:1.2\">Magnetic fields due to currents</h3>\n<p style=\"font-size:25px;line-height:1.5;color:#4A4842\">Explain the origin of the forces between current-carrying conductors, find their direction and calculate their size.</p>\n</div>\n</div>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">02 / 31</p>\n\n</section>"},{"id":"fields","title":"A third field of force","notes":"Students already know two fields of force. Build the table with them row by row. Ask: what has to be true about a charge for it to feel a magnetic force? Answer: it must be moving, and (as we will see) not along the field. B = F/(IL) is defined properly in Meeting 2; here it only shows the parallel with g and E.","html":"<section id=\"fields\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.1 · Concept of a magnetic field</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">A third field of force</h2>\n</div>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:42px;line-height:1.3;color:#1D1D1B;border-left:3px solid #B8391F;padding:4px 0px 4px 36px;width:1400px\"><i>A magnetic field is a region in which a moving charge, a current-carrying conductor or a magnetic material experiences a force.</i></p>\n<table style=\"font-size:27px;color:#1D1D1B\">\n<tr><th style=\"width:18%\">Field</th><th style=\"width:27%\">Produced by</th><th style=\"width:25%\">Acts on</th><th style=\"width:16%\">Strength</th><th style=\"width:14%\">Unit</th></tr>\n<tr><td>Gravitational</td><td>mass</td><td>mass</td><td><i>g</i> = <i>F</i> / <i>m</i></td><td>N kg⁻¹</td></tr>\n<tr><td>Electric</td><td>charge</td><td>charge</td><td><i>E</i> = <i>F</i> / <i>Q</i></td><td>N C⁻¹</td></tr>\n<tr style=\"background:#E6E2D8\"><td><b>Magnetic</b></td><td><b>moving</b> charge: currents, magnets</td><td><b>moving</b> charge: currents, magnetic materials</td><td><i>B</i> = <i>F</i> / (<i>IL</i>)</td><td>T</td></tr>\n</table>\n<p style=\"font-size:26px;line-height:1.45;color:#4A4842\">The essential difference: a charge at rest feels no magnetic force, however strong the field.</p>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">03 / 31</p>\n\n</section>"},{"id":"origin","title":"Every magnetic field comes from moving charge","notes":"The animation shows positive (conventional) charge carriers moving to the right and loops of B around the wire. Point out that the loops have no start or end: magnetic field lines always form closed loops, which is why there are no isolated magnetic poles. Electron spin is a quantum property; at this level it is enough to treat each electron as a tiny current loop.","html":"<section id=\"origin\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.1 · Origin of magnetic fields</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Every magnetic field comes from moving charge</h2>\n</div>\n<x-embed style=\"position:absolute;left:144px;top:330px;width:940px;height:460px\"><style>html,body{margin:0;background:#F3F1EC;overflow:hidden}canvas{display:block}</style><canvas id=\"c\"></canvas><script>\nconst W=900,H=440,c=document.getElementById('c'),x=c.getContext('2d');\nfunction fit(){const w=innerWidth,s=w/W,d=devicePixelRatio||1;c.width=w*d;c.height=w*H/W*d;c.style.width=w+'px';c.style.height=w*H/W+'px';x.setTransform(s*d,0,0,s*d,0,0);}\naddEventListener('resize',fit);fit();\nconst F='Arial, Helvetica, sans-serif',cy=230,rings=[220,450,680];\nfunction ring(cx,half,t){const rx=26,ry=110;x.lineWidth=3;x.strokeStyle='#1F6F78';x.beginPath();\n for(let i=0;i<=60;i++){const p=(half?0:Math.PI)+i/60*Math.PI;const X=cx+rx*Math.sin(p),Y=cy-ry*Math.cos(p);i?x.lineTo(X,Y):x.moveTo(X,Y);}x.stroke();\n for(let k=0;k<2;k++){const p=((t*0.9+k*Math.PI)%(2*Math.PI));const front=p<Math.PI;if(front!==half)continue;\n  const X=cx+rx*Math.sin(p),Y=cy-ry*Math.cos(p),dx=rx*Math.cos(p),dy=ry*Math.sin(p),a=Math.atan2(dy,dx);\n  x.save();x.translate(X,Y);x.rotate(a);x.fillStyle='#1F6F78';x.beginPath();x.moveTo(12,0);x.lineTo(-10,-9);x.lineTo(-10,9);x.closePath();x.fill();x.restore();}}\nfunction draw(ts){const t=ts/1000;x.fillStyle='#F3F1EC';x.fillRect(0,0,W,H);\n rings.forEach(r=>ring(r,false,t));\n const g=x.createLinearGradient(0,cy-14,0,cy+14);g.addColorStop(0,'#E0907E');g.addColorStop(.5,'#B8391F');g.addColorStop(1,'#7E2A18');\n x.fillStyle=g;x.fillRect(40,cy-14,820,28);\n for(let i=0;i<16;i++){const X=40+((i*51.25+t*70)%820);x.fillStyle='#F3F1EC';x.beginPath();x.arc(X,cy,8,0,7);x.fill();x.fillStyle='#B8391F';x.font='bold 14px '+F;x.textAlign='center';x.textBaseline='middle';x.fillText('+',X,cy+1);}\n rings.forEach(r=>ring(r,true,t));\n x.fillStyle='#B8391F';x.beginPath();x.moveTo(880,cy);x.lineTo(856,cy-16);x.lineTo(856,cy+16);x.closePath();x.fill();\n x.textAlign='left';x.textBaseline='alphabetic';x.font='26px '+F;x.fillStyle='#B8391F';x.fillText('moving charges (current I)',40,400);\n x.fillStyle='#1F6F78';x.fillText('closed loops of B around the path',470,400);\n x.font='26px '+F;x.fillStyle='#4A4842';x.fillText('At rest: E-field only.   In motion: B-field as well.',40,50);\n requestAnimationFrame(draw);}\nrequestAnimationFrame(draw);\n</script></x-embed>\n<p style=\"position:absolute;left:144px;top:808px;width:940px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Fig. 1  Conventional current and the loops of B around it</p>\n<div style=\"position:absolute;left:1148px;top:330px;width:628px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:12px;border-top:1px solid #1D1D1B;padding:20px 0px 0px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">01 · CURRENTS</p>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:32px;line-height:1.35;color:#1D1D1B\">Charge carriers drift along a wire. The field forms closed loops around the current.</p>\n</div>\n<div style=\"display:flex;flex-direction:column;gap:12px;border-top:1px solid #1D1D1B;padding:20px 0px 0px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#1F6F78\">02 · PERMANENT MAGNETS</p>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:32px;line-height:1.35;color:#1D1D1B\">Electron spin and orbital motion act as tiny current loops. In iron they line up in domains and their fields add.</p>\n</div>\n</div>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">04 / 31</p>\n\n</section>"},{"id":"fieldlines","title":"Four rules for field lines","notes":"Follow the moving compass in the animation: it always points along the line through its centre, so a field line is simply the path a compass would trace. Rule 4 is the deep one. Compare with electric field lines, which start on positive and end on negative charges. Magnetic field lines never end because there is no magnetic charge.","html":"<section id=\"fieldlines\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.1 · Representing a field</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Four rules for field lines</h2>\n</div>\n<div style=\"width:720px;display:grid;grid-template-columns:1fr 1fr;gap:36px 40px\">\n<div style=\"display:flex;flex-direction:column;gap:8px\"><p style=\"font-family:'Newsreader', Georgia, serif;font-size:64px;line-height:1;color:#1F6F78\">1</p><h3 style=\"font-size:28px;font-weight:600\">Direction</h3><p style=\"font-size:24px;line-height:1.45;color:#4A4842\">Where the N end of a compass points. Outside a magnet N to S, inside S to N.</p></div>\n<div style=\"display:flex;flex-direction:column;gap:8px\"><p style=\"font-family:'Newsreader', Georgia, serif;font-size:64px;line-height:1;color:#1F6F78\">2</p><h3 style=\"font-size:28px;font-weight:600\">Spacing</h3><p style=\"font-size:24px;line-height:1.45;color:#4A4842\">Closer lines mean a stronger field, a larger B.</p></div>\n<div style=\"display:flex;flex-direction:column;gap:8px\"><p style=\"font-family:'Newsreader', Georgia, serif;font-size:64px;line-height:1;color:#1F6F78\">3</p><h3 style=\"font-size:28px;font-weight:600\">Never cross</h3><p style=\"font-size:24px;line-height:1.45;color:#4A4842\">B has one direction at each point, so lines cannot meet.</p></div>\n<div style=\"display:flex;flex-direction:column;gap:8px\"><p style=\"font-family:'Newsreader', Georgia, serif;font-size:64px;line-height:1;color:#1F6F78\">4</p><h3 style=\"font-size:28px;font-weight:600\">Closed loops</h3><p style=\"font-size:24px;line-height:1.45;color:#4A4842\">No start and no end. There is no isolated N or S pole.</p></div>\n</div>\n<x-embed style=\"position:absolute;left:936px;top:310px;width:840px;height:579px\"><style>html,body{margin:0;background:#F3F1EC;overflow:hidden}canvas{display:block}</style><canvas id=\"c\"></canvas><script>\nconst W=900,H=620,c=document.getElementById('c'),x=c.getContext('2d');\nfunction fit(){const w=innerWidth,s=w/W,d=devicePixelRatio||1;c.width=w*d;c.height=w*H/W*d;c.style.width=w+'px';c.style.height=w*H/W+'px';x.setTransform(s*d,0,0,s*d,0,0);}\naddEventListener('resize',fit);fit();\nconst F='Arial, Helvetica, sans-serif',cx=450,cy=300,P=[{x:cx+105,y:cy,q:1},{x:cx-105,y:cy,q:-1}];\nfunction B(px,py){let bx=0,by=0;for(const p of P){const dx=px-p.x,dy=py-p.y,r=Math.hypot(dx,dy)+1e-6,k=p.q/(r*r*r);bx+=k*dx;by+=k*dy;}return[bx,by];}\nfunction trace(sx,sy,dir,end){const pts=[[sx,sy]];let X=sx,Y=sy;for(let i=0;i<1500;i++){let[bx,by]=B(X,Y);const m=Math.hypot(bx,by)*dir;X+=3*bx/m;Y+=3*by/m;pts.push([X,Y]);if(X<-20||X>W+20||Y<-20||Y>H+20)break;if(Math.hypot(X-end.x,Y-end.y)<10)return pts;}pts.open=1;return pts;}\nconst lines=[];for(let i=0;i<14;i++){const a=(i+.5)/14*2*Math.PI;lines.push(trace(P[0].x+10*Math.cos(a),P[0].y+10*Math.sin(a),1,P[1]));const l2=trace(P[1].x-10*Math.cos(a),P[1].y+10*Math.sin(a),-1,P[0]);if(l2.open)lines.push(l2);}\nconst needles=[];for(let gx=45;gx<W;gx+=70)for(let gy=40;gy<H-50;gy+=64){if(Math.abs(gx-cx)<160&&Math.abs(gy-cy)<62)continue;const[bx,by]=B(gx,gy);needles.push([gx,gy,Math.atan2(by,bx)]);}\nfunction needle(X,Y,a,L,w){x.save();x.translate(X,Y);x.rotate(a);x.fillStyle='#8E3324';x.beginPath();x.moveTo(L,0);x.lineTo(0,-w);x.lineTo(0,w);x.closePath();x.fill();x.fillStyle='#8E8A80';x.beginPath();x.moveTo(-L,0);x.lineTo(0,-w);x.lineTo(0,w);x.closePath();x.fill();x.restore();}\nconst path=lines[3];\nfunction draw(ts){const t=ts/1000;x.fillStyle='#F3F1EC';x.fillRect(0,0,W,H);\n x.strokeStyle='rgba(31,111,120,.5)';x.lineWidth=2;for(const l of lines){x.beginPath();l.forEach((p,i)=>i?x.lineTo(p[0],p[1]):x.moveTo(p[0],p[1]));x.stroke();}\n for(const n of needles)needle(n[0],n[1],n[2],15,5);\n x.fillStyle='#8E3324';x.fillRect(cx,cy-35,130,70);x.fillStyle='#1F6F78';x.fillRect(cx-130,cy-35,130,70);\n x.fillStyle='#F3F1EC';x.font='bold 40px '+F;x.textAlign='center';x.textBaseline='middle';x.fillText('N',cx+65,cy+2);x.fillText('S',cx-65,cy+2);\n const k=Math.floor((t*60)%path.length),p=path[k],[bx,by]=B(p[0],p[1]);\n x.fillStyle='#F3F1EC';x.strokeStyle='#1D1D1B';x.lineWidth=3;x.beginPath();x.arc(p[0],p[1],26,0,7);x.fill();x.stroke();needle(p[0],p[1],Math.atan2(by,bx),21,6);\n x.fillStyle='rgba(243,241,236,.92)';x.fillRect(0,570,W,50);x.textAlign='left';x.textBaseline='alphabetic';x.font='26px '+F;x.fillStyle='#1D1D1B';x.fillText('A compass needle lines up with B. Outside the magnet: N → S.',30,600);\n requestAnimationFrame(draw);}\nrequestAnimationFrame(draw);\n</script></x-embed>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">05 / 31</p>\n\n</section>"},{"id":"patterns","title":"Field patterns of permanent magnets","notes":"These patterns were computed, not drawn by hand, so the shapes are realistic. Exam sketches need: arrows on every line, lines leaving N and entering S, closer lines near the poles, and no crossing lines. For attraction, lines run straight across the gap. For repulsion, lines are pushed sideways and there is a neutral point X midway. Ask: why is X exactly midway? Because the magnets are identical.","html":"<section id=\"patterns\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.1 · Sketching field patterns</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Field patterns of permanent magnets</h2>\n</div>\n<x-embed style=\"position:absolute;left:144px;top:310px;width:1632px;height:549px\"><style>html,body{margin:0;background:#F3F1EC;overflow:hidden}canvas{display:block}</style><canvas id=\"c\"></canvas><script>\nconst W=1664,H=560,c=document.getElementById('c'),x=c.getContext('2d');\nfunction fit(){const w=innerWidth,s=w/W,d=devicePixelRatio||1;c.width=w*d;c.height=w*H/W*d;c.style.width=w+'px';c.style.height=w*H/W+'px';x.setTransform(s*d,0,0,s*d,0,0);}\nconst F='Arial, Helvetica, sans-serif',PW=554,PH=490,cy=245;\nconst panels=[\n {t:'Single bar magnet',m:[[277,75,1]]},\n {t:'Unlike poles facing: attraction',m:[[167,60,1],[387,60,1]]},\n {t:'Like poles facing: repulsion',m:[[167,60,1],[397,60,-1]],X:[282,cy]}];\nfunction poles(p){const P=[];for(const[mx,h,o]of p.m){const a=h*0.8;P.push({x:mx+o*a,y:cy,q:1});P.push({x:mx-o*a,y:cy,q:-1});}return P;}\nfunction B(P,px,py){let bx=0,by=0;for(const p of P){const dx=px-p.x,dy=py-p.y,r=Math.hypot(dx,dy)+1e-6,k=p.q/(r*r*r);bx+=k*dx;by+=k*dy;}return[bx,by];}\nfunction trace(P,sx,sy,d=1){const pts=[[sx,sy]];let X=sx,Y=sy;for(let i=0;i<1400;i++){const[bx,by]=B(P,X,Y),m=Math.hypot(bx,by)*d;if(Math.abs(m)<1e-12)break;X+=2.5*bx/m;Y+=2.5*by/m;pts.push([X,Y]);if(X<-5||X>PW+5||Y<-5||Y>PH+5){pts.out=1;break;}if(P.some(p=>p.q*d<0&&Math.hypot(X-p.x,Y-p.y)<8))break;}return pts;}\nfunction drawL(l){x.beginPath();l.forEach((q,j)=>j?x.lineTo(q[0],q[1]):x.moveTo(q[0],q[1]));x.stroke();}\nfunction arrow(X,Y,a){x.save();x.translate(X,Y);x.rotate(a);x.beginPath();x.moveTo(9,0);x.lineTo(-7,-7);x.lineTo(-7,7);x.closePath();x.fill();x.restore();}\nfunction panel(p,ox){x.save();x.translate(ox,0);x.beginPath();x.rect(0,0,PW,PH);x.clip();\n const P=poles(p);x.strokeStyle='#1F6F78';x.fillStyle='#1F6F78';x.lineWidth=2;\n for(const n of P.filter(q=>q.q>0))for(let i=0;i<12;i++){const a=(i+.5)/12*2*Math.PI,l=trace(P,n.x+8*Math.cos(a),n.y+8*Math.sin(a));x.beginPath();l.forEach((q,j)=>j?x.lineTo(q[0],q[1]):x.moveTo(q[0],q[1]));x.stroke();\n  const k=Math.min(l.length-2,Math.floor(l.length*(l.length>300?0.25:0.5)));if(k>2){const A=l[k],Bq=l[k+1];arrow(A[0],A[1],Math.atan2(Bq[1]-A[1],Bq[0]-A[0]));}}\n x.fillStyle='#1F6F78';for(const n of P.filter(q=>q.q<0))for(let i=0;i<12;i++){const a=(i+.5)/12*2*Math.PI,l=trace(P,n.x+8*Math.cos(a),n.y+8*Math.sin(a),-1);if(!l.out)continue;drawL(l);const k=Math.floor(l.length*0.35);if(k>2){const A=l[k+1],Bq=l[k];arrow(A[0],A[1],Math.atan2(Bq[1]-A[1],Bq[0]-A[0]));}}\n for(const[mx,h,o]of p.m){x.fillStyle='#8E3324';x.fillRect(o>0?mx:mx-h,cy-22,h,44);x.fillStyle='#1F6F78';x.fillRect(o>0?mx-h:mx,cy-22,h,44);\n  x.fillStyle='#F3F1EC';x.font='bold 28px '+F;x.textAlign='center';x.textBaseline='middle';x.fillText('N',mx+o*h/2,cy+1);x.fillText('S',mx-o*h/2,cy+1);}\n if(p.X){x.strokeStyle='#B8391F';x.lineWidth=4;const[X,Y]=p.X;x.beginPath();x.moveTo(X-10,Y-10);x.lineTo(X+10,Y+10);x.moveTo(X+10,Y-10);x.lineTo(X-10,Y+10);x.stroke();x.fillStyle='#B8391F';x.font='bold 26px '+F;x.fillText('X',X+24,Y-28);}\n x.restore();x.fillStyle='#1D1D1B';x.font='26px '+F;x.textAlign='center';x.textBaseline='alphabetic';x.fillText(p.t,ox+PW/2,H-18);\n x.strokeStyle='#CFCAC0';x.lineWidth=2;x.strokeRect(ox+1,1,PW-2,PH-2);}\nfunction draw(){fit();x.fillStyle='#F3F1EC';x.fillRect(0,0,W,H);panels.forEach((p,i)=>panel(p,i*(PW+1)));}\naddEventListener('resize',draw);draw();\n</script></x-embed>\n<p style=\"position:absolute;left:144px;top:878px;width:1632px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Fig. 2  Computed field lines. X marks a neutral point, where the two fields cancel and B = 0.</p>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">06 / 31</p>\n\n</section>"},{"id":"notation","title":"Dots, crosses and uniform fields","notes":"Many exam diagrams show a field into the page as a grid of crosses with a wire drawn across it. Practise reading both views.","html":"<section id=\"notation\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.1 · Drawing in three dimensions</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Dots, crosses and uniform fields</h2>\n</div>\n<div style=\"display:flex;flex:1\">\n<div style=\"width:760px;display:flex;flex-direction:column;gap:36px;padding:0px 56px 0px 0px;border-right:1px solid #BDB8AC\">\n<div style=\"display:flex;gap:40px;align-items:center\">\n<svg aria-label=\"Dot symbol: arrow tip coming out of the page\" width=\"140\" height=\"140\" viewBox=\"0 0 140 140\" style=\"width:140px;height:140px\"><circle cx=\"70\" cy=\"70\" r=\"58\" fill=\"none\" stroke=\"#B8391F\" stroke-width=\"5\"/><circle cx=\"70\" cy=\"70\" r=\"13\" fill=\"#B8391F\"/></svg>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:6px\"><p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">DOT</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:34px;line-height:1.3\">Out of the page: the tip of the arrow coming towards you.</p></div>\n</div>\n<div style=\"display:flex;gap:40px;align-items:center\">\n<svg aria-label=\"Cross symbol: arrow tail going into the page\" width=\"140\" height=\"140\" viewBox=\"0 0 140 140\" style=\"width:140px;height:140px\"><circle cx=\"70\" cy=\"70\" r=\"58\" fill=\"none\" stroke=\"#B8391F\" stroke-width=\"5\"/><path d=\"M42 42 L98 98 M98 42 L42 98\" stroke=\"#B8391F\" stroke-width=\"5\" stroke-linecap=\"round\"/></svg>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:6px\"><p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">CROSS</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:34px;line-height:1.3\">Into the page: the tail feathers moving away.</p></div>\n</div>\n<p style=\"font-size:25px;line-height:1.5;color:#4A4842\">The same symbols are used for currents and for fields.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:24px;padding:0px 0px 0px 56px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">UNIFORM FIELD</p>\n<svg aria-label=\"Uniform field between flat N and S pole pieces: parallel, equally spaced lines\" width=\"760\" height=\"270\" viewBox=\"0 0 760 270\" style=\"width:760px;height:270px\"><rect x=\"0\" y=\"0\" width=\"80\" height=\"270\" fill=\"#8E3324\"/><rect x=\"680\" y=\"0\" width=\"80\" height=\"270\" fill=\"#1F6F78\"/><g stroke=\"#1F6F78\" stroke-width=\"2\"><line x1=\"80\" y1=\"27\" x2=\"680\" y2=\"27\"/><line x1=\"80\" y1=\"81\" x2=\"680\" y2=\"81\"/><line x1=\"80\" y1=\"135\" x2=\"680\" y2=\"135\"/><line x1=\"80\" y1=\"189\" x2=\"680\" y2=\"189\"/><line x1=\"80\" y1=\"243\" x2=\"680\" y2=\"243\"/></g><g fill=\"#1F6F78\"><path d=\"M400 27 l-18 -9 l0 18 z\"/><path d=\"M400 81 l-18 -9 l0 18 z\"/><path d=\"M400 135 l-18 -9 l0 18 z\"/><path d=\"M400 189 l-18 -9 l0 18 z\"/><path d=\"M400 243 l-18 -9 l0 18 z\"/></g></svg>\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">N pole (left) · S pole (right)</p>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:32px;line-height:1.35\">Parallel, equally spaced, straight lines: the same B everywhere. Found between flat pole pieces and inside a long solenoid.</p>\n</div>\n</div>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">07 / 31</p>\n\n</section>"},{"id":"wire","title":"A long straight wire","notes":"The animation switches the current direction every six seconds. Ask students to predict the circulation before it flips, using the grip rule with their own right hand. The rings are spaced so that their density falls as 1/r; Meeting 3 turns this into B = μ0 I / (2πr). Note the arrows also move more slowly further out, another cue that B is weaker there.","html":"<section id=\"wire\" data-transition=\"fade\" style=\"background:#1E1F1C;color:#F1EEE6;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #6F6C64;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#E9846E\">§ 24.1 · Fields due to currents</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px;color:#F1EEE6\">A long straight wire</h2>\n</div>\n<x-embed style=\"position:absolute;left:144px;top:310px;width:780px;height:572px\"><style>html,body{margin:0;background:#F3F1EC;overflow:hidden}canvas{display:block}</style><canvas id=\"c\"></canvas><script>\nconst W=900,H=660,c=document.getElementById('c'),x=c.getContext('2d');\nfunction fit(){const w=innerWidth,s=w/W,d=devicePixelRatio||1;c.width=w*d;c.height=w*H/W*d;c.style.width=w+'px';c.style.height=w*H/W+'px';x.setTransform(s*d,0,0,s*d,0,0);}\naddEventListener('resize',fit);fit();\nconst F='Arial, Helvetica, sans-serif',cx=450,cy=320,R=[55,80,116,168,244];\nfunction draw(ts){const t=ts/1000,out=Math.floor(t/6)%2===0,s=out?-1:1;\n x.fillStyle='#F3F1EC';x.fillRect(0,0,W,H);\n R.forEach((r,i)=>{x.strokeStyle='#1F6F78';x.lineWidth=2.5;x.beginPath();x.arc(cx,cy,r,0,7);x.stroke();\n  const w=900/(r*r)*s;for(let k=0;k<4;k++){const a=t*w+k*Math.PI/2+i*0.6,X=cx+r*Math.cos(a),Y=cy+r*Math.sin(a);\n   x.save();x.translate(X,Y);x.rotate(a+s*Math.PI/2);x.fillStyle='#1F6F78';x.beginPath();x.moveTo(11,0);x.lineTo(-8,-8);x.lineTo(-8,8);x.closePath();x.fill();x.restore();}});\n x.fillStyle='#F3F1EC';x.strokeStyle='#B8391F';x.lineWidth=5;x.beginPath();x.arc(cx,cy,26,0,7);x.fill();x.stroke();\n x.fillStyle='#B8391F';x.strokeStyle='#B8391F';\n if(out){x.beginPath();x.arc(cx,cy,7,0,7);x.fill();}else{x.lineWidth=5;x.beginPath();x.moveTo(cx-13,cy-13);x.lineTo(cx+13,cy+13);x.moveTo(cx+13,cy-13);x.lineTo(cx-13,cy+13);x.stroke();}\n x.font='bold 28px '+F;x.textAlign='left';x.textBaseline='alphabetic';x.fillStyle='#B8391F';\n x.fillText(out?'I out of the page  ( • )':'I into the page  ( × )',24,44);\n x.fillStyle='#1F6F78';x.fillText(out?'B anticlockwise':'B clockwise',24,84);\n x.font='26px '+F;x.fillStyle='#4A4842';x.fillText('Rings spread out with distance: B ∝ 1/r',24,640);\n requestAnimationFrame(draw);}\nrequestAnimationFrame(draw);\n</script></x-embed>\n<div style=\"position:absolute;left:1000px;top:310px;width:776px;display:flex;flex-direction:column;gap:32px\">\n<div style=\"display:flex;flex-direction:column;gap:14px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#BDB8AC\">THE RIGHT-HAND GRIP RULE</p>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:40px;line-height:1.3;color:#F1EEE6\">Thumb along the <span style=\"color:#E9846E\">conventional current</span>; the curled fingers give the <span style=\"color:#7FB5BA\">direction of B</span>.</p>\n</div>\n<table style=\"font-size:26px;color:#F1EEE6\">\n<tr><th style=\"width:38%\">Feature</th><th style=\"width:62%\">Observation</th></tr>\n<tr><td>Shape</td><td>concentric circles in planes at 90° to the wire</td></tr>\n<tr><td>Distance</td><td>field weaker further away</td></tr>\n<tr><td>Current reversed</td><td>field reversed</td></tr>\n<tr><td>Larger current</td><td>stronger field</td></tr>\n</table>\n</div>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #4A4842\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#9A958A\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#9A958A;text-align:right\">08 / 31</p>\n\n</section>"},{"id":"solenoid","title":"A flat coil and a long solenoid","notes":"Both diagrams are cross-sections: each turn of wire cuts the page twice, once with current coming out (dot) and once going in (cross). Apply the grip rule to each wire and the fields add up inside. Pole rule: look at one end of the solenoid; if the current flows anticlockwise that end is N, clockwise is S. The iron core works because its domains line up with the solenoid field and add their own field, typically hundreds of times larger. Real solenoids are 3D, so the outside field spreads more than this 2D model shows.","html":"<section id=\"solenoid\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.1 · Fields due to currents</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">A flat coil and a long solenoid</h2>\n</div>\n<x-embed style=\"position:absolute;left:144px;top:310px;width:1632px;height:549px\"><style>html,body{margin:0;background:#F3F1EC;overflow:hidden}canvas{display:block}</style><canvas id=\"c\"></canvas><script>\nconst W=1664,H=560,c=document.getElementById('c'),x=c.getContext('2d');\nfunction fit(){const w=innerWidth,s=w/W,d=devicePixelRatio||1;c.width=w*d;c.height=w*H/W*d;c.style.width=w+'px';c.style.height=w*H/W+'px';x.setTransform(s*d,0,0,s*d,0,0);}\nconst F='Arial, Helvetica, sans-serif',PW=831,PH=490,cx=415,cy=240;\nfunction B(Wr,px,py){let bx=0,by=0;for(const w of Wr){const dx=px-w.x,dy=py-w.y,r2=dx*dx+dy*dy+1;bx+=w.I*dy/r2;by+=-w.I*dx/r2;}return[bx,by];}\nfunction trace(Wr,sx,sy,d){const pts=[[sx,sy]];let X=sx,Y=sy;for(let i=0;i<2600;i++){let[bx,by]=B(Wr,X,Y),m=Math.hypot(bx,by)*d;const MX=X+bx/m,MY=Y+by/m;[bx,by]=B(Wr,MX,MY);m=Math.hypot(bx,by)*d;X+=2*bx/m;Y+=2*by/m;pts.push([X,Y]);if(X<-5||X>PW+5||Y<-5||Y>PH+5)break;if(i>40&&Math.hypot(X-sx,Y-sy)<2.5){pts.closed=1;break;}if(Wr.some(w=>Math.hypot(X-w.x,Y-w.y)<6))break;}return pts;}\nfunction arrowAt(l,f){const k=Math.floor(l.length*f);if(k<2||k>=l.length-1)return;const A=l[k],Bq=l[k+1],a=Math.atan2(Bq[1]-A[1],Bq[0]-A[0]);x.save();x.translate(A[0],A[1]);x.rotate(a);x.beginPath();x.moveTo(9,0);x.lineTo(-7,-7);x.lineTo(-7,7);x.closePath();x.fill();x.restore();}\nfunction stroke(l){x.beginPath();l.forEach((q,j)=>j?x.lineTo(q[0],q[1]):x.moveTo(q[0],q[1]));x.stroke();}\nfunction wire(w){x.fillStyle='#F3F1EC';x.strokeStyle='#B8391F';x.lineWidth=3;x.beginPath();x.arc(w.x,w.y,12,0,7);x.fill();x.stroke();x.fillStyle='#B8391F';\n if(w.I>0){x.beginPath();x.arc(w.x,w.y,4,0,7);x.fill();}else{x.beginPath();x.moveTo(w.x-6,w.y-6);x.lineTo(w.x+6,w.y+6);x.moveTo(w.x+6,w.y-6);x.lineTo(w.x-6,w.y+6);x.stroke();}}\nfunction panel(Wr,seeds,ox,title,labels){x.save();x.translate(ox,0);x.beginPath();x.rect(0,0,PW,PH);x.clip();\n x.strokeStyle='#1F6F78';x.fillStyle='#1F6F78';x.lineWidth=2;\n for(const[sx,sy]of seeds){const f=trace(Wr,sx,sy,1);if(f.closed){stroke(f);arrowAt(f,0.02);arrowAt(f,0.5);}else{const b=trace(Wr,sx,sy,-1);stroke(f);stroke(b);arrowAt(f,0.35);x.save();arrowAt(b.slice().reverse(),0.6);x.restore();}}\n Wr.forEach(wire);x.font='bold 30px '+F;x.textAlign='center';x.textBaseline='middle';for(const[t,X,Y,col]of labels){x.fillStyle=col;x.fillText(t,X,Y);}\n x.restore();x.strokeStyle='#CFCAC0';x.lineWidth=2;x.strokeRect(ox+1,1,PW-2,PH-2);x.fillStyle='#1D1D1B';x.font='26px '+F;x.textAlign='center';x.textBaseline='alphabetic';x.fillText(title,ox+PW/2,H-18);}\nfunction coilPanel(){const a=90;x.save();x.beginPath();x.rect(0,0,PW,PH);x.clip();x.strokeStyle='#1F6F78';x.fillStyle='#1F6F78';x.lineWidth=2;\n x.beginPath();x.moveTo(cx,PH);x.lineTo(cx,0);x.stroke();\n const tri=(X,Y,a)=>{x.save();x.translate(X,Y);x.rotate(a);x.beginPath();x.moveTo(9,0);x.lineTo(-7,-7);x.lineTo(-7,7);x.closePath();x.fill();x.restore();};\n tri(cx,120,-Math.PI/2);tri(cx,380,-Math.PI/2);\n for(const x0 of [10,24,40,58]){const C=(x0*x0+a*a)/(2*x0),r=Math.sqrt(C*C-a*a);\n  for(const sg of[1,-1]){const X=cx+sg*C;x.beginPath();x.arc(X,cy,r,0,7);x.stroke();\n   tri(X,cy-r,sg>0?0:Math.PI);tri(X,cy+r,sg>0?Math.PI:0);}}\n [{x:cx-a,y:cy,I:1},{x:cx+a,y:cy,I:-1}].forEach(wire);\n x.font='bold 30px '+F;x.textAlign='center';x.textBaseline='middle';x.fillStyle='#8E3324';x.fillText('N',cx+30,40);x.fillStyle='#1F6F78';x.fillText('S',cx+30,450);\n x.restore();x.strokeStyle='#CFCAC0';x.lineWidth=2;x.strokeRect(1,1,PW-2,PH-2);x.fillStyle='#1D1D1B';x.font='26px '+F;x.textAlign='center';x.textBaseline='alphabetic';x.fillText('Flat circular coil (cut through its centre)',PW/2,H-18);}\nfunction draw(){fit();x.fillStyle='#F3F1EC';x.fillRect(0,0,W,H);\n coilPanel();\n const sol=[];for(let X=cx-200;X<=cx+200;X+=40){sol.push({x:X,y:cy-60,I:-1});sol.push({x:X,y:cy+60,I:1});}\n const s2=[];for(let Y=cy-36;Y<=cy+36;Y+=12)s2.push([cx,Y]);\n panel(sol,s2,PW+2,'Long solenoid: uniform field inside',[['N',cx-250,cy,'#8E3324'],['S',cx+250,cy,'#1F6F78']]);}\naddEventListener('resize',draw);draw();\n</script></x-embed>\n<p style=\"position:absolute;left:144px;top:876px;width:1632px;font-size:26px;line-height:1.4;color:#4A4842\">Inside a long solenoid B is <b style=\"color:#1D1D1B\">uniform and along the axis</b>; outside it resembles a bar magnet. A <b style=\"color:#1D1D1B\">ferrous (iron) core</b> makes B much stronger.</p>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">09 / 31</p>\n\n</section>"},{"id":"check1","title":"Think, pair, then reveal","notes":"In Present mode each click reveals the next answer. Give one minute per question for pair discussion first. For question 2, have every student physically make the grip with their right hand.","html":"<section id=\"check1\" data-transition=\"fade\" style=\"background:#E6E2D8;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">Check your understanding · Meeting 1</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Think, pair, then reveal</h2>\n</div>\n<div style=\"position:absolute;left:960px;top:310px;width:0px;height:600px;border-left:1px solid #9A958A\"></div>\n<div style=\"position:absolute;left:144px;top:610px;width:1632px;height:0px;border-top:1px solid #9A958A\"></div>\n<p style=\"position:absolute;left:144px;top:320px;width:60px;font-family:'Newsreader', Georgia, serif;font-size:56px;line-height:1;color:#1F6F78\">1</p>\n<p style=\"position:absolute;left:1000px;top:320px;width:60px;font-family:'Newsreader', Georgia, serif;font-size:56px;line-height:1;color:#1F6F78\">2</p>\n<p style=\"position:absolute;left:144px;top:640px;width:60px;font-family:'Newsreader', Georgia, serif;font-size:56px;line-height:1;color:#1F6F78\">3</p>\n<p style=\"position:absolute;left:1000px;top:640px;width:60px;font-family:'Newsreader', Georgia, serif;font-size:56px;line-height:1;color:#1F6F78\">4</p>\n<p style=\"position:absolute;left:220px;top:322px;width:700px;font-family:'Newsreader', Georgia, serif;font-size:32px;line-height:1.3\">Explain why two magnetic field lines can never cross.</p>\n<p style=\"position:absolute;left:1076px;top:322px;width:700px;font-family:'Newsreader', Georgia, serif;font-size:32px;line-height:1.3\">A long straight wire carries a current vertically upwards. Seen from above, which way does B circulate?</p>\n<p style=\"position:absolute;left:220px;top:642px;width:700px;font-family:'Newsreader', Georgia, serif;font-size:32px;line-height:1.3\">Two identical bar magnets have their N poles facing. Where is B equal to zero?</p>\n<p style=\"position:absolute;left:1076px;top:642px;width:700px;font-family:'Newsreader', Georgia, serif;font-size:32px;line-height:1.3\">The current in a solenoid is reversed and an iron core is pushed in. State two changes to the field.</p>\n<p data-build-in=\"fade order 1\" style=\"position:absolute;left:220px;top:470px;width:700px;font-size:25px;line-height:1.45;color:#1F6F78\">At a crossing B would point in two directions at once, but the resultant field at any point has only one direction.</p>\n<p data-build-in=\"fade order 2\" style=\"position:absolute;left:1076px;top:490px;width:700px;font-size:25px;line-height:1.45;color:#1F6F78\">Anticlockwise: thumb up along the current, fingers curl anticlockwise seen from above.</p>\n<p data-build-in=\"fade order 3\" style=\"position:absolute;left:220px;top:790px;width:700px;font-size:25px;line-height:1.45;color:#1F6F78\">At the neutral point midway between the poles, where the two fields are equal and opposite.</p>\n<p data-build-in=\"fade order 4\" style=\"position:absolute;left:1076px;top:810px;width:700px;font-size:25px;line-height:1.45;color:#1F6F78\">The poles swap (B reverses) and B becomes much stronger.</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">10 / 31</p>\n\n</section>"},{"id":"m2","title":"Force on a current-carrying conductor","notes":"Starter demo if available: a loose length of wire (or aluminium foil strip) between the poles of a strong U-shaped magnet jumps when a current from a low-voltage supply is switched on. Reverse the current or the magnet and it jumps the other way.","html":"<section id=\"m2\" data-transition=\"fade\" style=\"background:#B8391F;color:#F7EFE9;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px;display:flex;flex-direction:column;justify-content:space-between\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:2px;color:#F7EFE9\">MEETING 02 · § 24.2</p>\n<div style=\"display:flex;gap:80px;align-items:end\">\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:360px;font-weight:300;line-height:0.8;letter-spacing:-12px;color:#F7EFE9\">02</p>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:28px;padding:0px 0px 24px 0px\">\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:80px;font-weight:400;line-height:1.05;letter-spacing:-1px;color:#F7EFE9\">Force on a current-carrying conductor</h2>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:32px;line-height:1.4;color:#F7EFE9\"><i>Why does a wire in a magnetic field move? How big is the force, which way does it act, and how do we use it to define and measure B?</i></p>\n</div>\n</div>\n\n</section>"},{"id":"catapult","title":"Why the wire moves","notes":"The animation runs in three stages: the magnet’s field, the wire’s field, then their sum. Above the wire the two fields point the same way and add; below they point in opposite directions and partly cancel, with a neutral point just below the wire. Field lines act like stretched elastic bands that try to straighten, so they \"catapult\" the wire downwards. This is a model; the force itself comes from the field acting on the moving charges inside the wire, which we derive on slide 16.","html":"<section id=\"catapult\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.2 · The motor effect</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Why the wire moves</h2>\n</div>\n<div style=\"position:absolute;left:1040px;top:310px;width:736px;display:flex;flex-direction:column;gap:28px\">\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px;line-height:1.3;color:#1D1D1B\">A current-carrying conductor in a magnetic field, <i>not parallel to it</i>, experiences a force.</p>\n<ol style=\"font-size:26px;line-height:1.5;color:#4A4842\"><li>The magnet gives a uniform field.</li><li>The current gives circular field lines round the wire.</li><li>The fields add on one side and partly cancel on the other.</li><li>The wire is pushed from the strong side to the weak side.</li></ol>\n<p style=\"font-size:26px;line-height:1.45;color:#1D1D1B;border-top:1px solid #1D1D1B;padding:18px 0px 0px 0px\">The force is at right angles to <b>both</b> the current and the field.</p>\n</div>\n<x-embed style=\"position:absolute;left:144px;top:305px;width:840px;height:597px\"><style>html,body{margin:0;background:#F3F1EC;overflow:hidden}canvas{display:block}</style><canvas id=\"c\"></canvas><script>\nconst W=900,H=640,c=document.getElementById('c'),x=c.getContext('2d');\nfunction fit(){const w=innerWidth,s=w/W,d=devicePixelRatio||1;c.width=w*d;c.height=w*H/W*d;c.style.width=w+'px';c.style.height=w*H/W+'px';x.setTransform(s*d,0,0,s*d,0,0);}\naddEventListener('resize',fit);fit();\nconst F='Arial, Helvetica, sans-serif',L=70,R=830,cx=450,cy=300,K=-85;\nfunction Bw(px,py){const dx=px-cx,dy=py-cy,r2=dx*dx+dy*dy+4;return[K*dy/r2,-K*dx/r2];}\nfunction trace(sx,sy){const p=[[sx,sy]];let X=sx,Y=sy;for(let i=0;i<900;i++){let[a,b]=Bw(X,Y);a+=1;const m=Math.hypot(a,b);if(m<0.02)break;const mx=X+a/m,my=Y+b/m;let[a2,b2]=Bw(mx,my);a2+=1;const m2=Math.hypot(a2,b2);X+=2*a2/m2;Y+=2*b2/m2;p.push([X,Y]);if(X>R||Y<0||Y>590||Math.hypot(X-cx,Y-cy)<20)break;}return p;}\nconst comb=[];for(let y=24;y<590;y+=34)comb.push(trace(L,y));\nfunction tri(X,Y,a,s=1){x.save();x.translate(X,Y);x.rotate(a);x.beginPath();x.moveTo(10*s,0);x.lineTo(-8*s,-8*s);x.lineTo(-8*s,8*s);x.closePath();x.fill();x.restore();}\nfunction poles(){x.fillStyle='#8E3324';x.fillRect(0,0,L,590);x.fillStyle='#1F6F78';x.fillRect(R,0,W-R,590);x.fillStyle='#F3F1EC';x.font='bold 40px '+F;x.textAlign='center';x.textBaseline='middle';x.fillText('N',L/2,295);x.fillText('S',R+35,295);}\nfunction wire(dy){x.fillStyle='#F3F1EC';x.strokeStyle='#B8391F';x.lineWidth=5;x.beginPath();x.arc(cx,cy+dy,22,0,7);x.fill();x.stroke();x.beginPath();x.moveTo(cx-11,cy+dy-11);x.lineTo(cx+11,cy+dy+11);x.moveTo(cx+11,cy+dy-11);x.lineTo(cx-11,cy+dy+11);x.stroke();}\nfunction cap(t){x.fillStyle='#1D1D1B';x.font='26px '+F;x.textAlign='left';x.textBaseline='alphabetic';x.fillText(t,20,626);}\nfunction draw(ts){const t=(ts/1000)%14;x.fillStyle='#F3F1EC';x.fillRect(0,0,W,H);x.strokeStyle='#1F6F78';x.fillStyle='#1F6F78';x.lineWidth=2.2;\n if(t<3.5){for(let y=24;y<590;y+=34){x.beginPath();x.moveTo(L,y);x.lineTo(R,y);x.stroke();tri(450+((t*60)%120)-60,y,0);}poles();cap('1. Uniform field of the magnet (N → S)');}\n else if(t<7){for(const r of[45,75,115,170]){x.beginPath();x.arc(cx,cy,r,0,7);x.stroke();const a=(t*1.2)+r;tri(cx+r*Math.cos(a),cy+r*Math.sin(a),a+Math.PI/2);}poles();wire(0);cap('2. Field of the wire alone: I into the page, B clockwise');}\n else{for(const l of comb){x.beginPath();l.forEach((q,j)=>j?x.lineTo(q[0],q[1]):x.moveTo(q[0],q[1]));x.stroke();const k=Math.floor(l.length*0.15);if(l[k+1])tri(l[k][0],l[k][1],Math.atan2(l[k+1][1]-l[k][1],l[k+1][0]-l[k][0]));}\n  poles();const dy=Math.min(40,(t-7)*14);wire(dy);x.fillStyle='#B8391F';x.fillRect(cx-6,cy+dy+30,12,70);tri(cx,cy+dy+108,Math.PI/2,1.6);\n  x.font='bold 28px '+F;x.textAlign='left';x.fillText('F',cx+22,cy+dy+100);\n  x.font='bold 24px '+F;for(const[t,yy]of[['fields add: stronger B',cy-150],['fields cancel: weaker B',cy+190]]){const w=x.measureText(t).width;x.fillStyle='rgba(243,241,236,.92)';x.fillRect(cx+90,yy-26,w+16,36);x.fillStyle='#1D1D1B';x.fillText(t,cx+98,yy);}\n  cap('3. Combined (\"catapult\") field: the wire is pushed towards the weaker side');}\n requestAnimationFrame(draw);}\nrequestAnimationFrame(draw);\n</script></x-embed>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">12 / 31</p>\n\n</section>"},{"id":"flhr","title":"Fleming’s left-hand rule","notes":"The diagram is a perspective view: the current arrow points towards you, the field points right and the force points up. Check it against the catapult slide: field right, current into the page gave a downward force, so current out of the page gives an upward force. The rule uses conventional current; for a beam of electrons the current points opposite to their motion. The vector form is beyond the syllabus but useful for students who also take Further Mathematics.","html":"<section id=\"flhr\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.2 · Direction of the force</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Fleming’s left-hand rule</h2>\n</div>\n<div style=\"display:flex;gap:64px;flex:1\">\n<div style=\"position:relative;width:740px;height:600px\">\n<svg aria-label=\"Three mutually perpendicular arrows: force upwards, field to the right, current towards the viewer\" width=\"740\" height=\"600\" viewBox=\"0 0 740 600\" style=\"position:absolute;left:0px;top:0px;width:740px;height:600px\"><g stroke=\"#BDB8AC\" stroke-width=\"1.5\" stroke-dasharray=\"6 8\" fill=\"none\"><path d=\"M330 340 L330 580\"/><path d=\"M330 340 L40 340\"/><path d=\"M330 340 L480 190\"/></g><line x1=\"330\" y1=\"340\" x2=\"330\" y2=\"112\" stroke=\"#B8391F\" stroke-width=\"8\"/><path d=\"M330 74 L308 118 L352 118 Z\" fill=\"#B8391F\"/><line x1=\"330\" y1=\"340\" x2=\"622\" y2=\"340\" stroke=\"#1F6F78\" stroke-width=\"8\"/><path d=\"M664 340 L620 318 L620 362 Z\" fill=\"#1F6F78\"/><line x1=\"330\" y1=\"340\" x2=\"186\" y2=\"484\" stroke=\"#1D1D1B\" stroke-width=\"8\"/><path d=\"M156 514 L170 466 L204 500 Z\" fill=\"#1D1D1B\"/><circle cx=\"330\" cy=\"340\" r=\"10\" fill=\"#F3F1EC\" stroke=\"#1D1D1B\" stroke-width=\"3\"/></svg>\n<p style=\"position:absolute;left:366px;top:70px;width:340px;font-size:26px;line-height:1.3;color:#B8391F\"><b>thuMb</b><br>Motion (force)</p>\n<p style=\"position:absolute;left:470px;top:376px;width:260px;font-size:26px;line-height:1.3;color:#1F6F78\"><b>First finger</b><br>Field B</p>\n<p style=\"position:absolute;left:250px;top:470px;width:420px;font-size:26px;line-height:1.3;color:#1D1D1B\"><b>seCond finger</b><br>Current I (conventional)</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:32px\">\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px;line-height:1.3\">Hold the thumb and first two fingers of the <i>left</i> hand at right angles to one another.</p>\n<table style=\"font-size:27px;color:#1D1D1B\">\n<tr><th style=\"width:44%\">Digit</th><th style=\"width:56%\">Represents</th></tr>\n<tr><td>First finger</td><td><b>F</b>ield, N to S</td></tr>\n<tr><td>seCond finger</td><td><b>C</b>urrent, + to −</td></tr>\n<tr><td>thuMb</td><td><b>M</b>otion, the force</td></tr>\n</table>\n<div style=\"display:flex;flex-direction:column;gap:10px;border-top:1px solid #1D1D1B;padding:20px 0px 0px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">EXTENSION · VECTOR FORM</p>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:40px;color:#1D1D1B\"><b>F</b> = <i>I</i> <b>L</b> × <b>B</b></p>\n<p style=\"font-size:25px;line-height:1.45;color:#4A4842\">The cross product gives the size <i>BIL</i> sin <i>θ</i> and a direction perpendicular to both <b>L</b> and <b>B</b>.</p>\n</div>\n</div>\n</div>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">13 / 31</p>\n\n</section>"},{"id":"defineb","title":"Magnetic flux density, B","notes":"Click through the steps in Present mode. Stress that B is defined the same way g = F/m and E = F/Q are: force divided by \"what the field acts on\", here the current element IL. The name flux density looks ahead to electromagnetic induction, where B is the flux per unit area. A common exam request is the tesla in base units: from F = BIL, T = N / (A m) = (kg m s⁻²) / (A m) = kg s⁻² A⁻¹.","html":"<section id=\"defineb\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.2 · Deriving the definition</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Magnetic flux density, <i>B</i></h2>\n</div>\n<div data-build-in=\"fade order 1\" style=\"position:absolute;left:144px;top:310px;width:960px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:16px 0px 0px 0px\">\n<p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">01</p>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:4px\"><p style=\"font-size:24px;color:#6F6C64\">Experiment, wire at 90° to the field</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px\"><i>F</i> ∝ <i>I</i> (<i>L</i> fixed)      and      <i>F</i> ∝ <i>L</i> (<i>I</i> fixed)</p></div>\n</div>\n<div data-build-in=\"fade order 2\" style=\"position:absolute;left:144px;top:430px;width:960px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:16px 0px 0px 0px\">\n<p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">02</p>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:4px\"><p style=\"font-size:24px;color:#6F6C64\">Combine the two proportionalities</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px\"><i>F</i> ∝ <i>IL</i>    ⟹    <i>F</i> = <i>BIL</i></p></div>\n</div>\n<div data-build-in=\"fade order 3\" style=\"position:absolute;left:144px;top:550px;width:960px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:16px 0px 0px 0px\">\n<p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">03</p>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:8px\"><p style=\"font-size:24px;color:#6F6C64\">The constant depends only on the field. Rearrange to define it</p>\n<div style=\"display:flex;align-items:center;gap:18px\">\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:44px\"><i>B</i> =</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:2px\"><p style=\"font-family:'Newsreader', Georgia, serif;font-size:44px\"><i>F</i></p><div style=\"align-self:stretch;width:100px;height:0px;border-top:2px solid #1D1D1B\"></div><p style=\"font-family:'Newsreader', Georgia, serif;font-size:44px\"><i>IL</i></p></div>\n<p style=\"font-size:24px;color:#6F6C64\">wire perpendicular to B</p>\n</div></div>\n</div>\n<div data-build-in=\"fade order 4\" style=\"position:absolute;left:144px;top:780px;width:960px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:16px 0px 0px 0px\">\n<p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">04</p>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:4px\"><p style=\"font-size:24px;color:#6F6C64\">Units, using 1 N = 1 kg m s⁻²</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px\">1 T = 1 N A⁻¹ m⁻¹ = 1 kg s⁻² A⁻¹</p></div>\n</div>\n<div data-build-in=\"fade order 5\" style=\"position:absolute;left:1168px;top:310px;width:608px;display:flex;flex-direction:column;gap:22px;background:#1E1F1C;padding:40px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#E9846E\">DEFINITION</p>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:34px;line-height:1.35;color:#F1EEE6\">Magnetic flux density is the force per unit current per unit length on a straight conductor placed at right angles to the field.</p>\n<table style=\"font-size:25px;color:#F1EEE6\">\n<tr><th style=\"width:62%\">Typical field</th><th style=\"width:38%\">B / T</th></tr>\n<tr><td>Earth’s field, surface</td><td>≈ 5 × 10⁻⁵</td></tr>\n<tr><td>School U-magnet</td><td>≈ 0.1</td></tr>\n<tr><td>MRI scanner</td><td>1.5 to 3</td></tr>\n</table>\n</div>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">14 / 31</p>\n\n</section>"},{"id":"angle","title":"F = BIL sin θ","notes":"Equivalent view, shown in the animation: keep B whole and use only the part of the wire perpendicular to B, which has length L sin θ. Either way F = BIL sin θ. Watch the sine graph: the force is largest at 90° and falls to zero when the wire lies along the field. Common error: measuring θ from the normal to the field, which turns sin into cos.","html":"<section id=\"angle\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.2 · When the wire is not perpendicular</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\"><i>F</i> = <i>BIL</i> sin <i>θ</i></h2>\n</div>\n<x-embed style=\"position:absolute;left:144px;top:310px;width:840px;height:579px\"><style>html,body{margin:0;background:#F3F1EC;overflow:hidden}canvas{display:block}</style><canvas id=\"c\"></canvas><script>\nconst W=900,H=620,c=document.getElementById('c'),x=c.getContext('2d');\nfunction fit(){const w=innerWidth,s=w/W,d=devicePixelRatio||1;c.width=w*d;c.height=w*H/W*d;c.style.width=w+'px';c.style.height=w*H/W+'px';x.setTransform(s*d,0,0,s*d,0,0);}\naddEventListener('resize',fit);fit();\nconst F='Arial, Helvetica, sans-serif',ox=260,oy=300,Lw=170,g0=570,g1=870,gy0=500,gy1=230;\nfunction tri(X,Y,a,s=1,col){x.save();x.translate(X,Y);x.rotate(a);x.fillStyle=col;x.beginPath();x.moveTo(10*s,0);x.lineTo(-8*s,-8*s);x.lineTo(-8*s,8*s);x.closePath();x.fill();x.restore();}\nfunction draw(ts){const t=ts/1000,th=Math.PI/2*(1-Math.cos(2*Math.PI*t/12)),s=Math.sin(th),deg=th*180/Math.PI;\n x.fillStyle='#F3F1EC';x.fillRect(0,0,W,H);\n x.strokeStyle='rgba(31,111,120,.55)';x.lineWidth=2;for(let y=70;y<=540;y+=47){x.beginPath();x.moveTo(20,y);x.lineTo(500,y);x.stroke();tri(470,y,0,1,'rgba(31,111,120,.8)');}\n x.fillStyle='#1F6F78';x.font='bold 28px '+F;x.textAlign='left';x.fillText('B',30,50);\n const ex=ox+Lw*Math.cos(th),ey=oy-Lw*Math.sin(th),sx=ox-Lw*Math.cos(th),sy=oy+Lw*Math.sin(th);\n x.setLineDash([8,7]);x.strokeStyle='#1D1D1B';x.lineWidth=2.5;x.beginPath();x.moveTo(sx,sy);x.lineTo(sx,ey);x.stroke();x.setLineDash([]);\n x.fillStyle='#1D1D1B';x.font='24px '+F;x.fillText('L sinθ',sx-110<0?sx+10:sx-110,oy+8);\n x.strokeStyle='#B8391F';x.lineWidth=12;x.lineCap='round';x.beginPath();x.moveTo(sx,sy);x.lineTo(ex,ey);x.stroke();x.lineCap='butt';\n tri(ex,ey,-th,1.4,'#B8391F');x.fillStyle='#B8391F';x.font='bold 28px '+F;x.fillText('I',ex+14,ey-10);\n x.strokeStyle='#1D1D1B';x.lineWidth=2;x.beginPath();x.arc(ox,oy,60,-th,0);x.stroke();x.fillStyle='#1D1D1B';x.font='26px '+F;x.fillText('θ',ox+70,oy-18);\n const r=6+30*s;x.fillStyle='#F3F1EC';x.strokeStyle='#B8391F';x.lineWidth=4;x.beginPath();x.arc(ox,oy,r,0,7);x.fill();x.stroke();\n if(s>0.05){x.beginPath();x.moveTo(ox-r*.6,oy-r*.6);x.lineTo(ox+r*.6,oy+r*.6);x.moveTo(ox+r*.6,oy-r*.6);x.lineTo(ox-r*.6,oy+r*.6);x.stroke();}\n x.fillStyle='#1D1D1B';x.font='24px '+F;x.fillText('F into page, size ∝ sinθ',20,590);\n x.strokeStyle='#1D1D1B';x.lineWidth=2;x.beginPath();x.moveTo(g0,gy1-20);x.lineTo(g0,gy0);x.lineTo(g1+10,gy0);x.stroke();\n x.strokeStyle='#1F6F78';x.lineWidth=3;x.beginPath();for(let i=0;i<=90;i++){const a=i/90*Math.PI,X=g0+(g1-g0)*i/90,Y=gy0-(gy0-gy1)*Math.sin(a);i?x.lineTo(X,Y):x.moveTo(X,Y);}x.stroke();\n const dX=g0+(g1-g0)*th/Math.PI,dY=gy0-(gy0-gy1)*s;x.fillStyle='#B8391F';x.beginPath();x.arc(dX,dY,10,0,7);x.fill();\n x.fillStyle='#1D1D1B';x.font='24px '+F;x.textAlign='center';x.fillText('0',g0,gy0+30);x.fillText('90°',(g0+g1)/2,gy0+30);x.fillText('180°',g1,gy0+30);x.fillText('θ',(g0+g1)/2,gy0+62);\n x.textAlign='left';x.fillText('F / F max',g0+8,gy1-30);\n x.font='bold 28px '+F;x.fillText('θ = '+deg.toFixed(0)+'°',g0,100);x.fillStyle='#B8391F';x.fillText('F = '+s.toFixed(2)+' BIL',g0,145);\n requestAnimationFrame(draw);}\nrequestAnimationFrame(draw);\n</script></x-embed>\n<p style=\"position:absolute;left:1040px;top:310px;width:736px;font-family:'Newsreader', Georgia, serif;font-size:34px;line-height:1.3;color:#1D1D1B\"><i>θ</i> is the angle between the wire (the current) and the field.</p>\n<div data-build-in=\"fade order 1\" style=\"position:absolute;left:1040px;top:430px;width:736px;display:flex;gap:24px;border-top:1px solid #1D1D1B;padding:18px 0px 0px 0px\">\n<p style=\"width:64px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">01</p>\n<p style=\"flex:1;font-family:'Newsreader', Georgia, serif;font-size:30px;line-height:1.4;color:#1D1D1B\">along the wire: <i>B</i> cos <i>θ</i>, no force<br>across the wire: <i>B</i> sin <i>θ</i>, force</p>\n</div>\n<div data-build-in=\"fade order 2\" style=\"position:absolute;left:1040px;top:580px;width:736px;display:flex;gap:24px;border-top:1px solid #1D1D1B;padding:18px 0px 0px 0px\">\n<p style=\"width:64px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">02</p>\n<p style=\"flex:1;font-family:'Newsreader', Georgia, serif;font-size:34px;line-height:1.4;color:#1D1D1B\"><i>F</i> = (<i>B</i> sin <i>θ</i>) <i>IL</i> = <i>BIL</i> sin <i>θ</i></p>\n</div>\n<div data-build-in=\"fade order 3\" style=\"position:absolute;left:1040px;top:690px;width:736px;display:flex;gap:24px;border-top:1px solid #1D1D1B;padding:18px 0px 0px 0px\">\n<p style=\"width:64px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">03</p>\n<p style=\"flex:1;font-size:26px;line-height:1.5;color:#4A4842\"><i>θ</i> = 90°: <i>F</i> = <i>BIL</i>, the maximum.<br><i>θ</i> = 0° or 180°: <i>F</i> = 0, wire along the field.</p>\n</div>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">15 / 31</p>\n\n</section>"},{"id":"micro","title":"Where F = BIL comes from","notes":"This derivation connects Meeting 2 with topic 24.3 (charged particles in fields), where F = BQv sin θ is studied in its own right. Students met I = nAvq in the current electricity topic. The result shows why the force on a wire is the same whether the carriers are positive charges moving one way or electrons moving the other way: q and v both change sign, so qv, and therefore the force, is unchanged.","html":"<section id=\"micro\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">Going deeper · link to § 24.3</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Where <i>F</i> = <i>BIL</i> comes from</h2>\n</div>\n<svg aria-label=\"A section of wire of length L and cross-sectional area A, with positive charge carriers drifting at speed v, in a field into the page\" width=\"760\" height=\"300\" viewBox=\"0 0 760 300\" style=\"position:absolute;left:144px;top:320px;width:760px;height:300px\"><g stroke=\"#7FA9AD\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M40 30 l16 16 M56 30 l-16 16\"/><path d=\"M210 30 l16 16 M226 30 l-16 16\"/><path d=\"M380 30 l16 16 M396 30 l-16 16\"/><path d=\"M550 30 l16 16 M566 30 l-16 16\"/><path d=\"M700 30 l16 16 M716 30 l-16 16\"/><path d=\"M40 250 l16 16 M56 250 l-16 16\"/><path d=\"M210 250 l16 16 M226 250 l-16 16\"/><path d=\"M380 250 l16 16 M396 250 l-16 16\"/><path d=\"M550 250 l16 16 M566 250 l-16 16\"/><path d=\"M700 250 l16 16 M716 250 l-16 16\"/></g><rect x=\"90\" y=\"92\" width=\"560\" height=\"110\" fill=\"#EED9D2\" stroke=\"#B8391F\" stroke-width=\"3\"/><ellipse cx=\"650\" cy=\"147\" rx=\"24\" ry=\"55\" fill=\"#E3C0B5\" stroke=\"#B8391F\" stroke-width=\"3\"/><g fill=\"#B8391F\"><circle cx=\"150\" cy=\"122\" r=\"10\"/><circle cx=\"240\" cy=\"170\" r=\"10\"/><circle cx=\"330\" cy=\"120\" r=\"10\"/><circle cx=\"430\" cy=\"167\" r=\"10\"/><circle cx=\"520\" cy=\"124\" r=\"10\"/><circle cx=\"590\" cy=\"172\" r=\"10\"/></g><g stroke=\"#1D1D1B\" stroke-width=\"2\"><path d=\"M90 228 L650 228\"/><path d=\"M90 218 L90 238 M650 218 L650 238\"/></g><path d=\"M330 147 L402 147\" stroke=\"#1D1D1B\" stroke-width=\"3\"/><path d=\"M414 147 L398 138 L398 156 Z\" fill=\"#1D1D1B\"/></svg>\n<p style=\"position:absolute;left:144px;top:636px;width:760px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;line-height:1.45;color:#6F6C64\">Fig. 3  Length L, area A, n carriers per m³, each of charge q, drift speed v. Field B into the page.</p>\n<p data-build-in=\"fade order 6\" style=\"position:absolute;left:144px;top:760px;width:760px;font-family:'Newsreader', Georgia, serif;font-size:30px;line-height:1.35;color:#1D1D1B;border-left:3px solid #B8391F;padding:2px 0px 2px 28px\"><i>The force on the wire is the sum of the magnetic forces on its moving charges, passed to the metal lattice through collisions.</i></p>\n<div data-build-in=\"fade order 1\" style=\"position:absolute;left:984px;top:310px;width:792px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">01</p><div style=\"flex:1;display:flex;flex-direction:column;gap:2px\"><p style=\"font-size:24px;color:#6F6C64\">Current in terms of the carriers</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px\"><i>I</i> = <i>nAvq</i></p></div></div>\n<div data-build-in=\"fade order 2\" style=\"position:absolute;left:984px;top:425px;width:792px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">02</p><div style=\"flex:1;display:flex;flex-direction:column;gap:2px\"><p style=\"font-size:24px;color:#6F6C64\">Number of carriers in length L</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px\"><i>N</i> = <i>nAL</i></p></div></div>\n<div data-build-in=\"fade order 3\" style=\"position:absolute;left:984px;top:540px;width:792px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">03</p><div style=\"flex:1;display:flex;flex-direction:column;gap:2px\"><p style=\"font-size:24px;color:#6F6C64\">Force on one moving charge, v ⊥ B</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px\"><i>f</i> = <i>Bqv</i></p></div></div>\n<div data-build-in=\"fade order 4\" style=\"position:absolute;left:984px;top:655px;width:792px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">04</p><div style=\"flex:1;display:flex;flex-direction:column;gap:2px\"><p style=\"font-size:24px;color:#6F6C64\">Add the forces on all N carriers</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px\"><i>F</i> = <i>Nf</i> = (<i>nAL</i>)(<i>Bqv</i>)</p></div></div>\n<div data-build-in=\"fade order 5\" style=\"position:absolute;left:984px;top:770px;width:792px;display:flex;gap:28px;border-top:1px solid #1D1D1B;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">05</p><div style=\"flex:1;display:flex;flex-direction:column;gap:2px\"><p style=\"font-size:24px;color:#6F6C64\">Regroup to recognise I</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px\"><i>F</i> = <i>B</i>(<i>nAvq</i>)<i>L</i> = <span style=\"color:#B8391F\"><i>BIL</i></span></p></div></div>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">16 / 31</p>\n\n</section>"},{"id":"example1","title":"A wire at an angle to the field","notes":"Model the layout of a full-mark answer: equation, substitution with units converted, answer with unit and sensible significant figures (data are given to 2 s.f., so 0.15 N). Ask: what force would act if the wire were turned to lie along the field? Zero.","html":"<section id=\"example1\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">Worked example 1</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">A wire at an angle to the field</h2>\n</div>\n<div style=\"position:absolute;left:880px;top:310px;width:0px;height:600px;border-left:1px solid #BDB8AC\"></div>\n<div style=\"position:absolute;left:144px;top:310px;width:680px;display:flex;flex-direction:column;gap:22px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">PROBLEM</p>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:34px;line-height:1.35\">A straight wire of length 40 cm carries a current of 3.0 A. It lies at 30° to a uniform magnetic field of flux density 0.25 T.</p>\n<p style=\"font-size:26px;line-height:1.45;color:#4A4842\"><b style=\"color:#1D1D1B\">(a)</b> Calculate the force on the wire.</p>\n<p style=\"font-size:26px;line-height:1.45;color:#4A4842\"><b style=\"color:#1D1D1B\">(b)</b> Find the largest possible force for this wire and current, and the angle at which it acts.</p>\n<p style=\"font-size:26px;line-height:1.45;color:#4A4842\"><b style=\"color:#1D1D1B\">(c)</b> State the direction of the force.</p>\n</div>\n<p style=\"position:absolute;left:936px;top:310px;width:840px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">SOLUTION</p>\n<div data-build-in=\"fade order 1\" style=\"position:absolute;left:936px;top:370px;width:840px;display:flex;flex-direction:column;gap:6px\">\n<p style=\"font-size:24px;color:#6F6C64\">(a) Convert first: L = 0.40 m</p>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:34px;line-height:1.45\"><i>F</i> = <i>BIL</i> sin <i>θ</i> = 0.25 × 3.0 × 0.40 × sin 30°<br><span style=\"color:#B8391F\"><i>F</i> = 0.15 N</span></p>\n</div>\n<div data-build-in=\"fade order 2\" style=\"position:absolute;left:936px;top:560px;width:840px;display:flex;flex-direction:column;gap:6px;border-top:1px solid #BDB8AC;padding:16px 0px 0px 0px\">\n<p style=\"font-size:24px;color:#6F6C64\">(b) Largest when sin θ = 1, so θ = 90°</p>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:34px;line-height:1.45\"><i>F</i>max = <i>BIL</i> = 0.25 × 3.0 × 0.40<br><span style=\"color:#B8391F\"><i>F</i>max = 0.30 N at <i>θ</i> = 90°</span></p>\n</div>\n<div data-build-in=\"fade order 3\" style=\"position:absolute;left:936px;top:770px;width:840px;display:flex;flex-direction:column;gap:6px;border-top:1px solid #BDB8AC;padding:16px 0px 0px 0px\">\n<p style=\"font-size:24px;color:#6F6C64\">(c) Direction</p>\n<p style=\"font-size:26px;line-height:1.45\">Perpendicular to the plane containing the wire and the field; Fleming’s left-hand rule gives which side.</p>\n</div>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">17 / 31</p>\n\n</section>"},{"id":"balance","title":"Weighing a magnetic force","notes":"The animation uses B = 0.060 T and L = 5.0 cm, so each extra ampere adds 3.0 mN, about 0.31 g, to the reading. The wire is seen end-on with the current coming out of the page; the field points from N to S, so by the left-hand rule the force on the wire is upwards. This is the same Current Balance practical used in LKPD 2. If the reading falls instead of rising, the force on the wire is downwards: reverse the current or turn the magnet round.","html":"<section id=\"balance\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.2 · Measuring B with a current balance</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Weighing a magnetic force</h2>\n</div>\n<table style=\"width:740px;font-size:25px;color:#1D1D1B\">\n<tr><th style=\"width:14%\">Step</th><th style=\"width:86%\">Procedure</th></tr>\n<tr><td>1</td><td>Stand a U-shaped magnet on a top-pan balance; zero the reading.</td></tr>\n<tr><td>2</td><td>Clamp a stiff wire between the poles, at 90° to B, not touching the magnet.</td></tr>\n<tr><td>3</td><td>Pass a current I and record the new reading.</td></tr>\n<tr><td>4</td><td>Wire pushed up, so the magnet is pushed down (Newton’s third law): the reading rises by Δm.</td></tr>\n<tr><td>5</td><td>Repeat for several currents, and with the current reversed.</td></tr>\n</table>\n<x-embed style=\"position:absolute;left:936px;top:305px;width:840px;height:597px\"><style>html,body{margin:0;background:#F3F1EC;overflow:hidden}canvas{display:block}</style><canvas id=\"c\"></canvas><script>\nconst W=900,H=640,c=document.getElementById('c'),x=c.getContext('2d');\nfunction fit(){const w=innerWidth,s=w/W,d=devicePixelRatio||1;c.width=w*d;c.height=w*H/W*d;c.style.width=w+'px';c.style.height=w*H/W+'px';x.setTransform(s*d,0,0,s*d,0,0);}\naddEventListener('resize',fit);fit();\nconst F='Arial, Helvetica, sans-serif',B=0.060,L=0.050,g=9.81,m0=120.00,wx=250,wy=300;\nfunction tri(X,Y,a,s,col){x.save();x.translate(X,Y);x.rotate(a);x.fillStyle=col;x.beginPath();x.moveTo(10*s,0);x.lineTo(-8*s,-8*s);x.lineTo(-8*s,8*s);x.closePath();x.fill();x.restore();}\nfunction draw(ts){const t=(ts/1000)%12,I=Math.min(4,Math.floor(t/2)),Fw=B*I*L,dm=Fw/g*1000;\n x.fillStyle='#F3F1EC';x.fillRect(0,0,W,H);\n x.fillStyle='#8E8A80';x.fillRect(500,60,14,420);x.fillRect(250,60,264,12);x.fillRect(244,60,12,215);\n x.fillStyle='#4A4842';x.fillRect(60,470,380,90);x.fillStyle='#1D1D1B';x.fillRect(150,490,200,52);\n x.fillStyle='#7CE0B0';x.font='bold 34px \"Courier New\", monospace';x.textAlign='center';x.textBaseline='middle';x.fillText((m0+dm).toFixed(2)+' g',250,517);\n x.fillStyle='#8E8A80';x.fillRect(90,452,320,18);\n x.fillStyle='#55524B';x.fillRect(120,400,260,52);x.fillStyle='#8E3324';x.fillRect(120,230,80,170);x.fillStyle='#1F6F78';x.fillRect(300,230,80,170);\n x.fillStyle='#F3F1EC';x.font='bold 36px '+F;x.fillText('N',160,320);x.fillText('S',340,320);\n x.strokeStyle='rgba(31,111,120,.7)';x.lineWidth=2;for(const y of[255,285,345,375]){x.beginPath();x.moveTo(204,y);x.lineTo(296,y);x.stroke();tri(285,y,0,.8,'rgba(31,111,120,.9)');}\n x.fillStyle='#F3F1EC';x.strokeStyle='#B8391F';x.lineWidth=5;x.beginPath();x.arc(wx,wy+15,16,0,7);x.fill();x.stroke();x.fillStyle='#B8391F';x.beginPath();x.arc(wx,wy+15,5,0,7);x.fill();\n if(I>0){const h=18*I;x.fillStyle='#B8391F';x.fillRect(wx-5,wy-h-8,10,h);tri(wx,wy-h-14,-Math.PI/2,1.2,'#B8391F');\n  x.fillStyle='#1F6F78';x.fillRect(95,250,10,h);tri(100,250+h+8,Math.PI/2,1.2,'#1F6F78');}\n x.font='24px '+F;x.textAlign='left';x.fillStyle='#B8391F';x.fillText('F on wire (up)',268,170);x.fillStyle='#1F6F78';x.fillText('F on',20,150);x.fillText('magnet',20,178);x.fillText('(down)',20,206);\n x.fillStyle='#1D1D1B';x.font='bold 30px '+F;x.fillText('I = '+I.toFixed(1)+' A',40,40);x.font='24px '+F;x.fillText('wire length in field L = 5.0 cm',40,600);\n const g0=560,g1=860,gy0=420,gy1=150;x.strokeStyle='#1D1D1B';x.lineWidth=2;x.beginPath();x.moveTo(g0,gy1-10);x.lineTo(g0,gy0);x.lineTo(g1+10,gy0);x.stroke();\n x.font='24px '+F;x.fillStyle='#1D1D1B';x.textAlign='center';for(let i=0;i<=4;i++)x.fillText(i,g0+i*70,gy0+30);x.fillText('I / A',g0+150,gy0+62);\n x.textAlign='left';x.fillText('F = Δm g / mN',g0+6,gy1-28);\n x.strokeStyle='rgba(184,57,31,.5)';x.setLineDash([6,6]);x.beginPath();x.moveTo(g0,gy0);x.lineTo(g0+280,gy0-280*0.75);x.stroke();x.setLineDash([]);\n for(let i=0;i<=I;i++){x.fillStyle='#B8391F';x.beginPath();x.arc(g0+i*70,gy0-i*3.0*17.5,8,0,7);x.fill();}\n x.fillStyle='#1D1D1B';x.font='bold 26px '+F;x.fillText('gradient = BL',g0+10,520);x.font='24px '+F;x.fillText('Δm = '+dm.toFixed(3)+' g',g0+10,560);x.fillText('F = '+(Fw*1000).toFixed(2)+' mN',g0+10,594);\n requestAnimationFrame(draw);}\nrequestAnimationFrame(draw);\n</script></x-embed>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">18 / 31</p>\n\n</section>"},{"id":"balancemath","title":"From a balance reading to B","notes":"Step 2 is the conceptual heart: the balance measures the force on the magnet, not on the wire. Students often forget to convert grams to kilograms in step 1. The graph method in step 5 uses all the data and reduces the effect of random error in single readings; a non-zero intercept would show a systematic error such as a zero error on the balance.","html":"<section id=\"balancemath\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.2 · Measuring B: the analysis</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">From a balance reading to <i>B</i></h2>\n</div>\n<div data-build-in=\"fade order 1\" style=\"position:absolute;left:144px;top:310px;width:980px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">01</p><div style=\"flex:1;display:flex;flex-direction:column;gap:2px\"><p style=\"font-size:24px;color:#6F6C64\">Extra downward force on the magnet (Δm in kg)</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px\"><i>F</i>magnet = Δ<i>m g</i></p></div></div>\n<div data-build-in=\"fade order 2\" style=\"position:absolute;left:144px;top:420px;width:980px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">02</p><div style=\"flex:1;display:flex;flex-direction:column;gap:2px\"><p style=\"font-size:24px;color:#6F6C64\">Newton’s third law: an equal and opposite force on the wire</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px\"><i>F</i>wire = Δ<i>m g</i></p></div></div>\n<div data-build-in=\"fade order 3\" style=\"position:absolute;left:144px;top:530px;width:980px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">03</p><div style=\"flex:1;display:flex;flex-direction:column;gap:2px\"><p style=\"font-size:24px;color:#6F6C64\">Wire perpendicular to B, so use F = BIL</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px\">Δ<i>m g</i> = <i>BIL</i></p></div></div>\n<div data-build-in=\"fade order 4\" style=\"position:absolute;left:144px;top:640px;width:980px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">04</p><div style=\"flex:1;display:flex;flex-direction:column;gap:6px\"><p style=\"font-size:24px;color:#6F6C64\">Rearrange for B</p><div style=\"display:flex;align-items:center;gap:18px\"><p style=\"font-family:'Newsreader', Georgia, serif;font-size:40px\"><i>B</i> =</p><div style=\"display:flex;flex-direction:column;align-items:center;gap:2px\"><p style=\"font-family:'Newsreader', Georgia, serif;font-size:40px\">Δ<i>m g</i></p><div style=\"align-self:stretch;width:120px;height:0px;border-top:2px solid #1D1D1B\"></div><p style=\"font-family:'Newsreader', Georgia, serif;font-size:40px\"><i>IL</i></p></div></div></div></div>\n<div data-build-in=\"fade order 5\" style=\"position:absolute;left:144px;top:818px;width:980px;display:flex;gap:28px;border-top:1px solid #1D1D1B;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">05</p><p style=\"flex:1;font-family:'Newsreader', Georgia, serif;font-size:30px;line-height:1.3\">Better: plot Δ<i>m g</i> against <i>I</i>. Gradient = <i>BL</i>, so <i>B</i> = gradient ÷ <i>L</i>.</p></div>\n<div data-build-in=\"fade order 6\" style=\"position:absolute;left:1188px;top:310px;width:588px;display:flex;flex-direction:column;gap:18px;background:#E6E2D8;padding:36px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#1F6F78\">RELIABLE RESULTS</p>\n<p style=\"font-size:25px;line-height:1.45;color:#1D1D1B\"><b>Length L</b> is the wire inside the field, about the width of the pole faces; the field weakens at the edges.</p>\n<p style=\"font-size:25px;line-height:1.45;color:#1D1D1B\"><b>Heating:</b> use small currents for short times so readings do not drift.</p>\n<p style=\"font-size:25px;line-height:1.45;color:#1D1D1B\"><b>Offsets:</b> reverse the current and average the two readings.</p>\n<p style=\"font-size:25px;line-height:1.45;color:#1D1D1B\"><b>Alternative:</b> a calibrated Hall probe (§ 24.3).</p>\n</div>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">19 / 31</p>\n\n</section>"},{"id":"example2","title":"B from current balance data","notes":"A least-squares line through the origin gives the same gradient, 3.00 mN per ampere, so B = 0.060 T to 2 s.f. Extension: if L is 5.0 ± 0.2 cm and the gradient is ± 2%, the percentage uncertainty in B is 4% + 2% = 6%, so B = 0.060 ± 0.004 T. These are the same values used in the animation on slide 18.","html":"<section id=\"example2\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">Worked example 2 · data analysis</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\"><i>B</i> from current balance data</h2>\n</div>\n<div style=\"position:absolute;left:144px;top:310px;width:720px;display:flex;flex-direction:column;gap:26px\">\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:32px;line-height:1.35\">A wire with 5.0 cm inside the field is used in a current balance. Determine <i>B</i> and the direction of the force on the wire.</p>\n<table style=\"font-size:27px;color:#1D1D1B;font-variant-numeric:tabular-nums\">\n<tr><th style=\"width:24%;text-align:right\">I / A</th><th style=\"width:40%;text-align:right\">reading / g</th><th style=\"width:36%;text-align:right\">Δm / g</th></tr>\n<tr><td style=\"text-align:right\">0.0</td><td style=\"text-align:right\">120.00</td><td style=\"text-align:right\">0.00</td></tr>\n<tr><td style=\"text-align:right\">1.0</td><td style=\"text-align:right\">120.31</td><td style=\"text-align:right\">0.31</td></tr>\n<tr><td style=\"text-align:right\">2.0</td><td style=\"text-align:right\">120.61</td><td style=\"text-align:right\">0.61</td></tr>\n<tr><td style=\"text-align:right\">3.0</td><td style=\"text-align:right\">120.92</td><td style=\"text-align:right\">0.92</td></tr>\n<tr><td style=\"text-align:right\">4.0</td><td style=\"text-align:right\">121.22</td><td style=\"text-align:right\">1.22</td></tr>\n</table>\n</div>\n<div style=\"position:absolute;left:928px;top:310px;width:0px;height:600px;border-left:1px solid #BDB8AC\"></div>\n<div data-build-in=\"fade order 1\" style=\"position:absolute;left:984px;top:310px;width:792px;display:flex;flex-direction:column;gap:4px\"><p style=\"font-size:24px;color:#6F6C64\">01 · Δm is proportional to I, so the force is too</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:32px;line-height:1.4\">gradient of Δ<i>m</i> against <i>I</i> = 1.22 g ÷ 4.0 A = 0.305 g A⁻¹</p></div>\n<div data-build-in=\"fade order 2\" style=\"position:absolute;left:984px;top:450px;width:792px;display:flex;flex-direction:column;gap:4px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"font-size:24px;color:#6F6C64\">02 · Convert to force per ampere: g to kg, then × g</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:32px;line-height:1.4\"><i>F</i>/<i>I</i> = 0.305 × 10⁻³ × 9.81 = 2.99 × 10⁻³ N A⁻¹ = <i>BL</i></p></div>\n<div data-build-in=\"fade order 3\" style=\"position:absolute;left:984px;top:620px;width:792px;display:flex;flex-direction:column;gap:4px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"font-size:24px;color:#6F6C64\">03 · Divide by L = 0.050 m</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:32px;line-height:1.4\"><i>B</i> = 2.99 × 10⁻³ ÷ 0.050 = <span style=\"color:#B8391F\">0.060 T</span></p></div>\n<div data-build-in=\"fade order 4\" style=\"position:absolute;left:984px;top:740px;width:792px;display:flex;flex-direction:column;gap:4px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"font-size:24px;color:#6F6C64\">04 · Direction</p><p style=\"font-size:26px;line-height:1.45\">The reading rises, so the magnet is pushed down. By Newton’s third law the force on the wire is <b>upwards</b>.</p></div>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">20 / 31</p>\n\n</section>"},{"id":"pitfalls","title":"Six common mistakes, corrected","notes":"Use this as an exit check for Meeting 2: cover the correction column and ask students to fix each statement before revealing.","html":"<section id=\"pitfalls\" data-transition=\"fade\" style=\"background:#E6E2D8;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">Exit check · Meeting 2</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Six common mistakes, corrected</h2>\n</div>\n<table style=\"font-size:27px;color:#1D1D1B\">\n<tr><th style=\"width:8%\">No.</th><th style=\"width:40%\">Common mistake</th><th style=\"width:52%\">Correction</th></tr>\n<tr><td>1</td><td><i>“The force acts along the field.”</i></td><td>The force is at right angles to both B and I.</td></tr>\n<tr><td>2</td><td><i>Measuring θ from the normal.</i></td><td>θ is between the wire and the field; parallel gives F = 0.</td></tr>\n<tr><td>3</td><td><i>Using the whole length of wire.</i></td><td>Only the length inside the field counts.</td></tr>\n<tr><td>4</td><td><i>Right hand for the force.</i></td><td>Left hand for force; right-hand grip for the field of a current.</td></tr>\n<tr><td>5</td><td><i>Electron flow as the current.</i></td><td>The rules use conventional current, opposite to electron motion.</td></tr>\n<tr><td>6</td><td><i>Field lines as real paths.</i></td><td>They are a model; their direction and spacing describe B.</td></tr>\n</table>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">21 / 31</p>\n\n</section>"},{"id":"m3","title":"Magnetic fields due to currents","notes":"Recap question to open: a wire carries a current in a magnetic field. What two things set the direction of the force? Then bridge: a current makes a field, and a current in a field feels a force, so two currents must exert forces on each other.","html":"<section id=\"m3\" data-transition=\"fade\" style=\"background:#1F6F78;color:#EEF4F3;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px;display:flex;flex-direction:column;justify-content:space-between\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:2px;color:#EEF4F3\">MEETING 03 · § 24.4</p>\n<div style=\"display:flex;gap:80px;align-items:end\">\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:360px;font-weight:300;line-height:0.8;letter-spacing:-12px;color:#EEF4F3\">03</p>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:28px;padding:0px 0px 24px 0px\">\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:80px;font-weight:400;line-height:1.05;letter-spacing:-1px;color:#EEF4F3\">Magnetic fields due to currents</h2>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:32px;line-height:1.4;color:#EEF4F3\"><i>How strong is the field near a wire or inside a solenoid, and why do two currents push or pull on each other?</i></p>\n</div>\n</div>\n\n</section>"},{"id":"wireformulas","title":"Near a wire, and inside a solenoid","notes":"These two results come from Ampère’s law, which is beyond A Level; students use them, not derive them. The 1/r dependence matches the spreading rings in the Meeting 1 animation. Note that B = μ0 n I contains n, turns per unit length, not the total number of turns N. Check the current syllabus for which of these formulas are listed for recall in your exam series.","html":"<section id=\"wireformulas\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.4 · How strong is the field?</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Near a wire, and inside a solenoid</h2>\n</div>\n<div style=\"display:flex;flex:1\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:22px;padding:0px 56px 0px 0px;border-right:1px solid #BDB8AC\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#1F6F78\">LONG STRAIGHT WIRE</p>\n<div style=\"display:flex;align-items:center;justify-content:space-between\">\n<div style=\"display:flex;align-items:center;gap:18px\">\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:60px\"><i>B</i> =</p>\n<div style=\"display:flex;flex-direction:column;align-items:center;gap:2px\"><p style=\"font-family:'Newsreader', Georgia, serif;font-size:60px\"><i>μ</i>₀<i>I</i></p><div style=\"align-self:stretch;width:150px;height:0px;border-top:2px solid #1D1D1B\"></div><p style=\"font-family:'Newsreader', Georgia, serif;font-size:60px\">2π<i>r</i></p></div>\n</div>\n<svg aria-label=\"Graph of B against distance r: B falls as 1 over r\" width=\"280\" height=\"190\" viewBox=\"0 0 280 190\" style=\"width:280px;height:190px\"><path d=\"M20 8 L20 172 L272 172\" fill=\"none\" stroke=\"#1D1D1B\" stroke-width=\"2\"/><path d=\"M34 14 C 56 110, 110 140, 268 156\" fill=\"none\" stroke=\"#1F6F78\" stroke-width=\"3\"/></svg>\n</div>\n<p style=\"font-size:25px;line-height:1.5;color:#4A4842\">r is the perpendicular distance from the wire. Double the distance, halve the field.</p>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:28px;line-height:1.45;border-top:1px solid #BDB8AC;padding:18px 0px 0px 0px\"><i>I</i> = 10 A, <i>r</i> = 5.0 cm: <i>B</i> = (4π × 10⁻⁷ × 10) ÷ (2π × 0.050) = 4.0 × 10⁻⁵ T, close to the Earth’s field.</p>\n</div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:22px;padding:0px 0px 0px 56px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">LONG SOLENOID</p>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:60px;line-height:1.2\"><i>B</i> = <i>μ</i>₀<i>nI</i></p>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:32px;color:#4A4842\"><i>n</i> = <i>N</i> / <i>l</i>, turns per metre</p>\n<p style=\"font-size:25px;line-height:1.5;color:#4A4842\">Inside, away from the ends, B does not depend on the radius of the solenoid or the position.</p>\n<p style=\"font-size:25px;line-height:1.5;color:#4A4842\">A <b style=\"color:#1D1D1B\">ferrous core</b> multiplies B many times: the iron becomes magnetised and adds its own field.</p>\n</div>\n</div>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">μ₀ = 4π × 10⁻⁷ H m⁻¹ (permeability of free space)</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">23 / 31</p>\n\n</section>"},{"id":"parallel","title":"Two parallel wires","notes":"The animation shows a top view with both wires perpendicular to the page and alternates between like and unlike currents every eight seconds. Teal arrows show the field each wire produces at the other; red arrows show the forces. The field lines are calculated from the two currents, not sketched. The next slide works through the direction argument step by step.","html":"<section id=\"parallel\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.4 · Forces between currents</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Two parallel wires</h2>\n</div>\n<div style=\"position:absolute;left:1040px;top:310px;width:736px;display:flex;flex-direction:column;gap:30px\">\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:36px;line-height:1.3;color:#1D1D1B\">Each wire sits in the magnetic field of the other, so each feels a force <i>F</i> = <i>BIL</i>.</p>\n<div style=\"display:flex;border-top:1px solid #1D1D1B;border-bottom:1px solid #1D1D1B\">\n<div style=\"flex:1;display:flex;flex-direction:column;gap:6px;padding:20px 20px 20px 0px;border-right:1px solid #1D1D1B\"><p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">LIKE CURRENTS</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:44px;color:#B8391F\">attract</p></div>\n<div style=\"flex:1;display:flex;flex-direction:column;gap:6px;padding:20px 0px 20px 28px\"><p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">UNLIKE CURRENTS</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:44px;color:#1F6F78\">repel</p></div>\n</div>\n<p style=\"font-size:25px;line-height:1.5;color:#4A4842\">For like currents the field lines wrap round both wires and draw them together; for unlike currents they crowd between the wires and push them apart. This is the reverse of charges and poles.</p>\n</div>\n<x-embed style=\"position:absolute;left:144px;top:305px;width:840px;height:597px\"><style>html,body{margin:0;background:#F3F1EC;overflow:hidden}canvas{display:block}</style><canvas id=\"c\"></canvas><script>\nconst W=900,H=640,c=document.getElementById('c'),x=c.getContext('2d');\nfunction fit(){const w=innerWidth,s=w/W,d=devicePixelRatio||1;c.width=w*d;c.height=w*H/W*d;c.style.width=w+'px';c.style.height=w*H/W+'px';x.setTransform(s*d,0,0,s*d,0,0);}\naddEventListener('resize',fit);fit();\nconst F='Arial, Helvetica, sans-serif',cy=310,A={x:310,y:cy},Bw={x:590,y:cy};\nfunction Bf(Wr,px,py){let bx=0,by=0;for(const w of Wr){const dx=px-w.x,dy=py-w.y,r2=dx*dx+dy*dy+1;bx+=w.I*dy/r2;by+=-w.I*dx/r2;}return[bx,by];}\nfunction trace(Wr,sx,sy){const p=[[sx,sy]];let X=sx,Y=sy;for(let i=0;i<5000;i++){let[a,b]=Bf(Wr,X,Y),m=Math.hypot(a,b);if(m<1e-9)break;const mx=X+a/m,my=Y+b/m;[a,b]=Bf(Wr,mx,my);m=Math.hypot(a,b);X+=2*a/m;Y+=2*b/m;p.push([X,Y]);if(i>60&&Math.hypot(X-sx,Y-sy)<2.2)break;if(X<-200||X>W+200||Y<-200||Y>H+200)break;}return p;}\nfunction build(I2){const Wr=[{x:A.x,y:cy,I:1},{x:Bw.x,y:cy,I:I2}],L=[];\n const seeds=I2>0?[A.x-30,A.x-55,A.x-90,A.x+30,A.x+60,Bw.x-30,Bw.x-60,Bw.x+30,Bw.x+55,Bw.x+90,120,60,20]:[A.x-30,A.x-60,A.x-100,A.x-160,A.x+30,A.x+60,A.x+100];\n for(const s of seeds){const l=trace(Wr,s,cy);L.push(l);if(I2<0){L.push(l.map(q=>[W-q[0],q[1]]));}}return L;}\nconst same=build(1),opp=build(-1);\nfunction tri(X,Y,a,s,col){x.save();x.translate(X,Y);x.rotate(a);x.fillStyle=col;x.beginPath();x.moveTo(10*s,0);x.lineTo(-8*s,-8*s);x.lineTo(-8*s,8*s);x.closePath();x.fill();x.restore();}\nfunction wire(w,I){x.fillStyle='#F3F1EC';x.strokeStyle='#B8391F';x.lineWidth=5;x.beginPath();x.arc(w.x,w.y,20,0,7);x.fill();x.stroke();x.fillStyle='#B8391F';x.strokeStyle='#B8391F';\n if(I>0){x.beginPath();x.arc(w.x,w.y,6,0,7);x.fill();}else{x.beginPath();x.moveTo(w.x-10,w.y-10);x.lineTo(w.x+10,w.y+10);x.moveTo(w.x+10,w.y-10);x.lineTo(w.x-10,w.y+10);x.stroke();}}\nfunction arrowV(X,Y,dx,dy,col){x.strokeStyle=col;x.lineWidth=8;x.beginPath();x.moveTo(X,Y);x.lineTo(X+dx,Y+dy);x.stroke();tri(X+dx,Y+dy,Math.atan2(dy,dx),1.4,col);}\nfunction draw(ts){const t=(ts/1000)%16,s=t<8,L=s?same:opp,p=0.6+0.4*Math.sin(ts/300);\n x.fillStyle='#F3F1EC';x.fillRect(0,0,W,H);x.strokeStyle='rgba(31,111,120,.55)';x.lineWidth=2;\n for(const l of L){x.beginPath();l.forEach((q,j)=>j?x.lineTo(q[0],q[1]):x.moveTo(q[0],q[1]));x.stroke();}\n wire(A,1);wire(Bw,s?1:-1);\n arrowV(Bw.x+40,cy,0,-90,'#1F6F78');arrowV(A.x-40,cy,0,s?90:-90,'#1F6F78');\n const f=70*p;arrowV(Bw.x+(s?-28:28),cy+60,s?-f:f,0,'#B8391F');arrowV(A.x+(s?28:-28),cy+60,s?f:-f,0,'#B8391F');\n x.font='26px '+F;x.textAlign='left';x.fillStyle='#1F6F78';x.fillText('B₁ at wire 2',Bw.x+58,cy-70);x.fillText('B₂ at wire 1',A.x-210,cy+(s?95:-70));\n x.fillStyle='#B8391F';x.font='bold 26px '+F;x.fillText('F',Bw.x+(s?-80:110),cy+105);x.fillText('F',A.x+(s?70:-100),cy+105);\n x.fillStyle='#1D1D1B';x.font='bold 30px '+F;x.fillText(s?'Currents in the SAME direction: wires ATTRACT':'Currents in OPPOSITE directions: wires REPEL',24,44);\n x.font='26px '+F;x.fillText('wire 1',A.x-38,cy+170);x.fillText('wire 2',Bw.x-38,cy+170);\n x.fillStyle='rgba(243,241,236,.92)';x.fillRect(0,588,W,52);x.fillStyle='#4A4842';x.fillText('Each wire feels F = BIL in the field of the other wire.',24,622);\n requestAnimationFrame(draw);}\nrequestAnimationFrame(draw);\n</script></x-embed>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">24 / 31</p>\n\n</section>"},{"id":"paralleldir","title":"Finding the direction, step by step","notes":"This is the explanation examiners want for \"explain the origin of the forces\": one wire produces a field at the other; the other carries a current across that field, so it experiences a force F = BIL; the forces form a Newton’s third law pair. Students must name the rule used at each step. A neat check for step 3: field up, current out of the page, so the force is current × field = out × up, which points left.","html":"<section id=\"paralleldir\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.4 · Explaining the origin of the force</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Finding the direction, step by step</h2>\n</div>\n<svg aria-label=\"Top view of two parallel wires, both with current out of the page. Field lines of wire 1 circle it anticlockwise; at wire 2 the field of wire 1 points up the page and the force on wire 2 points left, towards wire 1\" width=\"760\" height=\"480\" viewBox=\"0 0 760 480\" style=\"position:absolute;left:144px;top:320px;width:760px;height:480px\"><g fill=\"none\" stroke=\"#7FA9AD\" stroke-width=\"2\"><circle cx=\"230\" cy=\"240\" r=\"70\"/><circle cx=\"230\" cy=\"240\" r=\"140\"/><circle cx=\"230\" cy=\"240\" r=\"210\"/></g><g fill=\"#1F6F78\"><path d=\"M216 170 l16 -9 l0 18 z\"/><path d=\"M244 310 l-16 -9 l0 18 z\"/><path d=\"M90 254 l-9 -16 l18 0 z\"/></g><line x1=\"510\" y1=\"240\" x2=\"510\" y2=\"122\" stroke=\"#1F6F78\" stroke-width=\"7\"/><path d=\"M510 88 L492 126 L528 126 Z\" fill=\"#1F6F78\"/><line x1=\"480\" y1=\"312\" x2=\"382\" y2=\"312\" stroke=\"#B8391F\" stroke-width=\"7\"/><path d=\"M348 312 L386 294 L386 330 Z\" fill=\"#B8391F\"/><circle cx=\"230\" cy=\"240\" r=\"20\" fill=\"#F3F1EC\" stroke=\"#B8391F\" stroke-width=\"4\"/><circle cx=\"230\" cy=\"240\" r=\"6\" fill=\"#B8391F\"/><circle cx=\"510\" cy=\"240\" r=\"20\" fill=\"#F3F1EC\" stroke=\"#B8391F\" stroke-width=\"4\"/><circle cx=\"510\" cy=\"240\" r=\"6\" fill=\"#B8391F\"/></svg>\n<p style=\"position:absolute;left:144px;top:820px;width:760px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;line-height:1.45;color:#6F6C64\">Fig. 4  Top view, both currents out of the page. Teal: B₁ at wire 2. Red: force on wire 2.</p>\n<div data-build-in=\"fade order 1\" style=\"position:absolute;left:984px;top:310px;width:792px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">01</p><div style=\"flex:1;display:flex;flex-direction:column;gap:4px\"><p style=\"font-size:24px;color:#6F6C64\">Field of wire 1</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:30px;line-height:1.35\">Current out of the page: by the right-hand grip rule B₁ circles anticlockwise.</p></div></div>\n<div data-build-in=\"fade order 2\" style=\"position:absolute;left:984px;top:460px;width:792px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">02</p><div style=\"flex:1;display:flex;flex-direction:column;gap:4px\"><p style=\"font-size:24px;color:#6F6C64\">B₁ at the position of wire 2</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:30px;line-height:1.35\">Wire 2 is to the right of wire 1, where B₁ points up the page.</p></div></div>\n<div data-build-in=\"fade order 3\" style=\"position:absolute;left:984px;top:610px;width:792px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">03</p><div style=\"flex:1;display:flex;flex-direction:column;gap:4px\"><p style=\"font-size:24px;color:#6F6C64\">Force on wire 2, by the left-hand rule</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:30px;line-height:1.35\">Current out of the page in an upward field gives a force to the left: <i>towards wire 1</i>.</p></div></div>\n<div data-build-in=\"fade order 4\" style=\"position:absolute;left:984px;top:760px;width:792px;display:flex;gap:28px;border-top:1px solid #1D1D1B;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">04</p><div style=\"flex:1;display:flex;flex-direction:column;gap:4px\"><p style=\"font-size:24px;color:#6F6C64\">Wire 1, and the reversed case</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:30px;line-height:1.35\">Wire 1 is pushed right: they <i>attract</i>. Reverse one current and they <i>repel</i>.</p></div></div>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">25 / 31</p>\n\n</section>"},{"id":"parallelmath","title":"Force per unit length between two wires","notes":"Point out the symmetry of the result in I1 and I2: this is why the forces are equal, which Newton’s third law demands. The ampere is now defined by fixing the value of the elementary charge e, so μ0 is now a measured quantity very close to 4π × 10⁻⁷ H m⁻¹.","html":"<section id=\"parallelmath\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">§ 24.4 · Deriving the size of the force</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Force per unit length between two wires</h2>\n</div>\n<div data-build-in=\"fade order 1\" style=\"position:absolute;left:144px;top:310px;width:1000px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">01</p><div style=\"flex:1;display:flex;flex-direction:column;gap:6px\"><p style=\"font-size:24px;color:#6F6C64\">Field of wire 1 at distance d, where wire 2 sits</p><div style=\"display:flex;align-items:center;gap:16px\"><p style=\"font-family:'Newsreader', Georgia, serif;font-size:38px\"><i>B</i>₁ =</p><div style=\"display:flex;flex-direction:column;align-items:center;gap:2px\"><p style=\"font-family:'Newsreader', Georgia, serif;font-size:38px\"><i>μ</i>₀<i>I</i>₁</p><div style=\"align-self:stretch;width:110px;height:0px;border-top:2px solid #1D1D1B\"></div><p style=\"font-family:'Newsreader', Georgia, serif;font-size:38px\">2π<i>d</i></p></div></div></div></div>\n<div data-build-in=\"fade order 2\" style=\"position:absolute;left:144px;top:500px;width:1000px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">02</p><div style=\"flex:1;display:flex;flex-direction:column;gap:4px\"><p style=\"font-size:24px;color:#6F6C64\">Wire 2 carries I₂ at right angles to B₁; on a length L</p><p style=\"font-family:'Newsreader', Georgia, serif;font-size:38px\"><i>F</i> = <i>B</i>₁<i>I</i>₂<i>L</i></p></div></div>\n<div data-build-in=\"fade order 3\" style=\"position:absolute;left:144px;top:620px;width:1000px;display:flex;gap:28px;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">03</p><div style=\"flex:1;display:flex;flex-direction:column;gap:6px\"><p style=\"font-size:24px;color:#6F6C64\">Substitute B₁ and divide by L</p><div style=\"display:flex;align-items:center;gap:16px\"><p style=\"font-family:'Newsreader', Georgia, serif;font-size:38px\"><i>F</i> / <i>L</i> =</p><div style=\"display:flex;flex-direction:column;align-items:center;gap:2px\"><p style=\"font-family:'Newsreader', Georgia, serif;font-size:38px;color:#B8391F\"><i>μ</i>₀<i>I</i>₁<i>I</i>₂</p><div style=\"align-self:stretch;width:150px;height:0px;border-top:2px solid #B8391F\"></div><p style=\"font-family:'Newsreader', Georgia, serif;font-size:38px;color:#B8391F\">2π<i>d</i></p></div></div></div></div>\n<div data-build-in=\"fade order 4\" style=\"position:absolute;left:144px;top:810px;width:1000px;display:flex;gap:28px;border-top:1px solid #1D1D1B;padding:14px 0px 0px 0px\"><p style=\"width:60px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#B8391F\">04</p><p style=\"flex:1;font-family:'Newsreader', Georgia, serif;font-size:28px;line-height:1.35\">Swap the labels: wire 1 feels a force of the same size, even if <i>I</i>₁ ≠ <i>I</i>₂. A Newton’s third law pair.</p></div>\n<div data-build-in=\"fade order 5\" style=\"position:absolute;left:1208px;top:310px;width:568px;display:flex;flex-direction:column;gap:18px;background:#1E1F1C;padding:36px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#E9846E\">CHECK THE UNITS</p>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:30px;line-height:1.4;color:#F1EEE6\">(T m A⁻¹)(A)(A) ÷ m = T A = N m⁻¹</p>\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#7FB5BA\">A PIECE OF HISTORY</p>\n<p style=\"font-size:25px;line-height:1.5;color:#BDB8AC\">Until 2019 the ampere was defined with this result: 1 A in each of two wires 1 m apart gives 2 × 10⁻⁷ N on each metre. Check: μ₀ / 2π = 2 × 10⁻⁷.</p>\n</div>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">26 / 31</p>\n\n</section>"},{"id":"example3","title":"Force between wires, and a zero-field point","notes":"For (a), μ0 / 2π = 2 × 10⁻⁷ makes the arithmetic quick: B1 = 2 × 10⁻⁷ × 5.0 / 0.040. For (b), the μ0 and 2π cancel, so the condition is simply I1 / x = I2 / (d − x). Ask: if the currents were in opposite directions, where would the zero-field point be? Outside the pair, on the side of the smaller current: 6/x = 2/(x − 0.08) gives x = 0.12 m, that is 4.0 cm beyond the 2.0 A wire.","html":"<section id=\"example3\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">Worked example 3</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Force between wires, and a zero-field point</h2>\n</div>\n<div style=\"position:absolute;left:960px;top:310px;width:0px;height:600px;border-left:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;top:310px;width:770px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#1F6F78\">(a) FORCE</p>\n<p style=\"position:absolute;left:1006px;top:310px;width:770px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#1F6F78\">(b) ZERO FIELD</p>\n<p style=\"position:absolute;left:144px;top:356px;width:770px;font-family:'Newsreader', Georgia, serif;font-size:30px;line-height:1.35\">Two long parallel wires 4.0 cm apart carry 5.0 A and 2.0 A in the same direction. Find the force on 0.50 m of each wire.</p>\n<p style=\"position:absolute;left:1006px;top:356px;width:770px;font-family:'Newsreader', Georgia, serif;font-size:30px;line-height:1.35\">Two parallel wires 8.0 cm apart carry 6.0 A and 2.0 A in the same direction. Where between them is B = 0?</p>\n<p data-build-in=\"fade order 1\" style=\"position:absolute;left:144px;top:510px;width:770px;font-family:'Newsreader', Georgia, serif;font-size:30px;line-height:1.5\"><i>B</i>₁ = (4π × 10⁻⁷ × 5.0) ÷ (2π × 0.040)<br><i>B</i>₁ = 2.5 × 10⁻⁵ T</p>\n<p data-build-in=\"fade order 2\" style=\"position:absolute;left:144px;top:640px;width:770px;font-family:'Newsreader', Georgia, serif;font-size:30px;line-height:1.5;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><i>F</i> = <i>B</i>₁<i>I</i>₂<i>L</i> = 2.5 × 10⁻⁵ × 2.0 × 0.50<br><span style=\"color:#B8391F\"><i>F</i> = 2.5 × 10⁻⁵ N, attractive, on each wire</span></p>\n<p data-build-in=\"fade order 3\" style=\"position:absolute;left:1006px;top:480px;width:770px;font-size:25px;line-height:1.45;color:#4A4842\">Between like currents the two fields point in opposite directions, so they can cancel there. Let x be the distance from the 6.0 A wire.</p>\n<p data-build-in=\"fade order 4\" style=\"position:absolute;left:1006px;top:610px;width:770px;font-family:'Newsreader', Georgia, serif;font-size:30px;line-height:1.5;border-top:1px solid #BDB8AC;padding:14px 0px 0px 0px\"><i>μ</i>₀(6.0) ÷ 2π<i>x</i> = <i>μ</i>₀(2.0) ÷ 2π(0.080 − <i>x</i>)<br>6.0(0.080 − <i>x</i>) = 2.0<i>x</i>   ⟹   0.48 = 8.0<i>x</i></p>\n<p data-build-in=\"fade order 5\" style=\"position:absolute;left:1006px;top:760px;width:770px;font-family:'Newsreader', Georgia, serif;font-size:30px;line-height:1.5;border-top:1px solid #1D1D1B;padding:14px 0px 0px 0px\"><span style=\"color:#B8391F\"><i>x</i> = 0.060 m, 6.0 cm from the 6.0 A wire</span><br><span style=\"color:#4A4842\"><i>closer to the smaller current</i></span></p>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">27 / 31</p>\n\n</section>"},{"id":"mcq","title":"Questions 1 to 3","notes":"Give two minutes for all three, then reveal one answer per click. In question 1, distractor D comes from dividing by sin 60° instead of multiplying. In question 3 many students pick C because Y has the larger current; F/L = μ0 I1 I2 / (2πd) is symmetric in the two currents.","html":"<section id=\"mcq\" data-transition=\"fade\" style=\"background:#E6E2D8;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">Practice · multiple choice</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Questions 1 to 3</h2>\n</div>\n<div style=\"position:absolute;left:688px;top:310px;width:0px;height:600px;border-left:1px solid #9A958A\"></div>\n<div style=\"position:absolute;left:1232px;top:310px;width:0px;height:600px;border-left:1px solid #9A958A\"></div>\n<p style=\"position:absolute;left:144px;top:310px;width:510px;font-family:'Newsreader', Georgia, serif;font-size:56px;line-height:1;color:#1F6F78\">1</p>\n<p style=\"position:absolute;left:722px;top:310px;width:480px;font-family:'Newsreader', Georgia, serif;font-size:56px;line-height:1;color:#1F6F78\">2</p>\n<p style=\"position:absolute;left:1266px;top:310px;width:480px;font-family:'Newsreader', Georgia, serif;font-size:56px;line-height:1;color:#1F6F78\">3</p>\n<p style=\"position:absolute;left:144px;top:386px;width:510px;font-family:'Newsreader', Georgia, serif;font-size:28px;line-height:1.35\">A wire 0.20 m long carries 4.0 A at 60° to a field of 0.050 T. What is the force on it?</p>\n<p style=\"position:absolute;left:722px;top:386px;width:480px;font-family:'Newsreader', Georgia, serif;font-size:28px;line-height:1.35\">Which is the tesla expressed in SI base units?</p>\n<p style=\"position:absolute;left:1266px;top:386px;width:510px;font-family:'Newsreader', Georgia, serif;font-size:28px;line-height:1.35\">Parallel wires X and Y carry I and 3I in the same direction. The force on X is F. What is the force on Y?</p>\n<p style=\"position:absolute;left:144px;top:540px;width:510px;font-size:26px;line-height:1.65;color:#4A4842\"><b>A</b>   2.0 × 10⁻² N<br><b>B</b>   3.5 × 10⁻² N<br><b>C</b>   4.0 × 10⁻² N<br><b>D</b>   4.6 × 10⁻² N</p>\n<p style=\"position:absolute;left:722px;top:540px;width:480px;font-size:26px;line-height:1.65;color:#4A4842\"><b>A</b>   kg s⁻² A⁻¹<br><b>B</b>   kg m s⁻² A⁻¹<br><b>C</b>   kg A s⁻²<br><b>D</b>   kg m² s⁻² A⁻¹</p>\n<p style=\"position:absolute;left:1266px;top:540px;width:510px;font-size:26px;line-height:1.65;color:#4A4842\"><b>A</b>   F/3, attractive<br><b>B</b>   F, attractive<br><b>C</b>   3F, attractive<br><b>D</b>   F, repulsive</p>\n<p data-build-in=\"fade order 1\" style=\"position:absolute;left:144px;top:740px;width:510px;font-size:24px;line-height:1.45;color:#1F6F78;border-top:1px solid #1F6F78;padding:12px 0px 0px 0px\"><b>B.</b> F = 0.050 × 4.0 × 0.20 × sin 60° = 0.0346 N. A uses cos 60°; C ignores the angle.</p>\n<p data-build-in=\"fade order 2\" style=\"position:absolute;left:722px;top:740px;width:480px;font-size:24px;line-height:1.45;color:#1F6F78;border-top:1px solid #1F6F78;padding:12px 0px 0px 0px\"><b>A.</b> T = N A⁻¹ m⁻¹ = (kg m s⁻²) ÷ (A m) = kg s⁻² A⁻¹.</p>\n<p data-build-in=\"fade order 3\" style=\"position:absolute;left:1266px;top:740px;width:510px;font-size:24px;line-height:1.45;color:#1F6F78;border-top:1px solid #1F6F78;padding:12px 0px 0px 0px\"><b>B.</b> The forces are a Newton’s third law pair, so they are equal. Like currents attract.</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">28 / 31</p>\n\n</section>"},{"id":"q4","title":"Question 4: a current balance","notes":"Mark scheme style: (a) 1 mark for the force on the current-carrying wire in the field, 1 mark for Newton’s third law acting on the magnet. (b) 1 mark for converting Δm to force, 1 for B = F/(IL), 1 for the answer 0.031 T. (c) Downwards. (d) 153.36 g.","html":"<section id=\"q4\" data-transition=\"fade\" style=\"background:#E6E2D8;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">Practice · structured question</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Question 4: a current balance</h2>\n</div>\n<div style=\"position:absolute;left:144px;top:310px;width:740px;display:flex;flex-direction:column;gap:18px\">\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:29px;line-height:1.4\">A U-shaped magnet stands on a top-pan balance. A horizontal wire is clamped between its poles, with 6.0 cm of wire in the field and at right angles to it. With no current the reading is 152.40 g; with a current of 2.5 A it is 151.92 g.</p>\n<table style=\"font-size:25px;color:#1D1D1B\">\n<tr><th style=\"width:10%\">Part</th><th style=\"width:76%\">Task</th><th style=\"width:14%;text-align:right\">Marks</th></tr>\n<tr><td>(a)</td><td>Explain why the reading changes.</td><td style=\"text-align:right\">2</td></tr>\n<tr><td>(b)</td><td>Calculate the magnetic flux density.</td><td style=\"text-align:right\">3</td></tr>\n<tr><td>(c)</td><td>State the direction of the force on the wire.</td><td style=\"text-align:right\">1</td></tr>\n<tr><td>(d)</td><td>Predict the reading if I is doubled and reversed.</td><td style=\"text-align:right\">1</td></tr>\n</table>\n</div>\n<div style=\"position:absolute;left:928px;top:310px;width:0px;height:600px;border-left:1px solid #9A958A\"></div>\n<p data-build-in=\"fade order 1\" style=\"position:absolute;left:976px;top:310px;width:800px;font-size:25px;line-height:1.45\"><b>(a)</b> The field exerts a force on the current in the wire. By Newton’s third law the wire exerts an equal and opposite force on the magnet, which changes the reading.</p>\n<p data-build-in=\"fade order 2\" style=\"position:absolute;left:976px;top:450px;width:800px;font-family:'Newsreader', Georgia, serif;font-size:28px;line-height:1.5;border-top:1px solid #9A958A;padding:14px 0px 0px 0px\"><b>(b)</b> Δ<i>m</i> = 0.48 g = 4.8 × 10⁻⁴ kg; <i>F</i> = 4.8 × 10⁻⁴ × 9.81 = 4.71 × 10⁻³ N<br><i>B</i> = <i>F</i> ÷ <i>IL</i> = 4.71 × 10⁻³ ÷ (2.5 × 0.060) = <span style=\"color:#B8391F\">0.031 T</span></p>\n<p data-build-in=\"fade order 3\" style=\"position:absolute;left:976px;top:640px;width:800px;font-size:25px;line-height:1.45;border-top:1px solid #9A958A;padding:14px 0px 0px 0px\"><b>(c)</b> The reading falls, so the force on the magnet is upwards; the force on the wire is therefore <b>downwards</b>.</p>\n<p data-build-in=\"fade order 4\" style=\"position:absolute;left:976px;top:770px;width:800px;font-size:25px;line-height:1.45;border-top:1px solid #9A958A;padding:14px 0px 0px 0px\"><b>(d)</b> The force doubles and reverses, pushing the magnet down by the weight of 0.96 g: 152.40 + 0.96 = <b>153.36 g</b>.</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">29 / 31</p>\n\n</section>"},{"id":"q56","title":"Questions 5 and 6","notes":"Question 5: 4π × 10⁻⁷ × 2400 = 3.02 × 10⁻³ T. A common error is to use N = 500 instead of n = N / l. Question 6: I = 2.45 A, which rounds to 2.5 A at 2 s.f. Extension for fast finishers: if the field were tilted at 30° to the wire, what current would be needed? I = 2.45 / sin 30° = 4.9 A.","html":"<section id=\"q56\" data-transition=\"fade\" style=\"background:#E6E2D8;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">Practice · structured questions</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Questions 5 and 6</h2>\n</div>\n<div style=\"position:absolute;left:960px;top:310px;width:0px;height:600px;border-left:1px solid #9A958A\"></div>\n<p style=\"position:absolute;left:144px;top:310px;width:60px;font-family:'Newsreader', Georgia, serif;font-size:56px;line-height:1;color:#1F6F78\">5</p>\n<p style=\"position:absolute;left:1006px;top:310px;width:60px;font-family:'Newsreader', Georgia, serif;font-size:56px;line-height:1;color:#1F6F78\">6</p>\n<p style=\"position:absolute;left:220px;top:314px;width:700px;font-family:'Newsreader', Georgia, serif;font-size:29px;line-height:1.4\">A solenoid 25 cm long has 500 turns and carries 1.2 A. (a) Calculate B inside it, away from the ends. [2] (b) An iron rod is pushed inside. State and explain the effect on B. [2]</p>\n<p style=\"position:absolute;left:1082px;top:314px;width:694px;font-family:'Newsreader', Georgia, serif;font-size:29px;line-height:1.4\">A straight horizontal wire with mass per unit length 0.020 kg m⁻¹ lies at right angles to a horizontal field of 0.080 T. Find the current that lets it float, the magnetic force balancing its weight. [3]</p>\n<p data-build-in=\"fade order 1\" style=\"position:absolute;left:220px;top:560px;width:700px;font-family:'Newsreader', Georgia, serif;font-size:28px;line-height:1.5;border-top:1px solid #9A958A;padding:14px 0px 0px 0px\"><b>(a)</b> <i>n</i> = 500 ÷ 0.25 = 2000 m⁻¹<br><i>B</i> = <i>μ</i>₀<i>nI</i> = 4π × 10⁻⁷ × 2000 × 1.2 = <span style=\"color:#B8391F\">3.0 × 10⁻³ T</span></p>\n<p data-build-in=\"fade order 2\" style=\"position:absolute;left:220px;top:720px;width:700px;font-size:25px;line-height:1.45;border-top:1px solid #9A958A;padding:14px 0px 0px 0px\"><b>(b)</b> B increases greatly: the iron is magnetised by the solenoid field, its domains line up and add their own field.</p>\n<p data-build-in=\"fade order 3\" style=\"position:absolute;left:1082px;top:560px;width:694px;font-family:'Newsreader', Georgia, serif;font-size:28px;line-height:1.5;border-top:1px solid #9A958A;padding:14px 0px 0px 0px\"><i>BIL</i> = <i>mg</i>   ⟹   <i>I</i> = (<i>m</i>/<i>L</i>)<i>g</i> ÷ <i>B</i><br><i>I</i> = 0.020 × 9.81 ÷ 0.080 = <span style=\"color:#B8391F\">2.5 A</span></p>\n<p data-build-in=\"fade order 4\" style=\"position:absolute;left:1082px;top:720px;width:694px;font-size:25px;line-height:1.45;border-top:1px solid #9A958A;padding:14px 0px 0px 0px\">The current must flow in the direction that gives an <b>upward</b> force by Fleming’s left-hand rule. The length L cancels.</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">30 / 31</p>\n\n</section>"},{"id":"summary","title":"Key results of the topic","notes":"Close by asking students to link each row back to one of the two big ideas. Next in the sequence: 24.3, the force on a single moving charge, F = BQv sin θ, and its applications, including the Hall effect, a Hall probe for measuring B, and charged particles in circular paths.","html":"<section id=\"summary\" data-transition=\"fade\" style=\"background:#F3F1EC;color:#1D1D1B;font-family:'Public Sans', Arial, sans-serif;padding:120px 144px 168px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:16px;border-bottom:1px solid #1D1D1B;padding:0px 0px 24px 0px\">\n<p style=\"font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;letter-spacing:1px;color:#B8391F\">Summary · formula sheet</p>\n<h2 style=\"font-family:'Newsreader', Georgia, serif;font-size:68px;font-weight:500;line-height:1.05;letter-spacing:-1px\">Key results of the topic</h2>\n</div>\n<table style=\"font-size:27px;color:#1D1D1B\">\n<tr><th style=\"width:27%\">Situation</th><th style=\"width:35%\">Result</th><th style=\"width:38%\">Remember</th></tr>\n<tr><td>Force on a conductor</td><td><i>F</i> = <i>BIL</i> sin <i>θ</i></td><td>θ between wire and field</td></tr>\n<tr><td>Definition of B</td><td><i>B</i> = <i>F</i> / (<i>IL</i>), wire ⊥ B</td><td>1 T = 1 N A⁻¹ m⁻¹</td></tr>\n<tr><td>Current balance</td><td><i>B</i> = Δ<i>m g</i> / (<i>IL</i>)</td><td>Newton’s third law on the magnet</td></tr>\n<tr><td>Long straight wire</td><td><i>B</i> = <i>μ</i>₀<i>I</i> / (2π<i>r</i>)</td><td>B ∝ 1/r; right-hand grip rule</td></tr>\n<tr><td>Long solenoid</td><td><i>B</i> = <i>μ</i>₀<i>nI</i></td><td>n = turns per metre; iron boosts B</td></tr>\n<tr><td>Two parallel wires</td><td><i>F</i> / <i>L</i> = <i>μ</i>₀<i>I</i>₁<i>I</i>₂ / (2π<i>d</i>)</td><td>like currents attract</td></tr>\n</table>\n<p style=\"font-family:'Newsreader', Georgia, serif;font-size:34px;line-height:1.35;border-left:3px solid #B8391F;padding:2px 0px 2px 32px\"><i>Moving charge makes magnetic fields, and magnetic fields push on moving charge. Every result here follows from those two ideas.</i></p>\n<div style=\"position:absolute;left:144px;top:960px;width:1632px;height:0px;border-top:1px solid #BDB8AC\"></div>\n<p style=\"position:absolute;left:144px;bottom:64px;width:1000px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64\">Magnetic fields · 9702</p>\n<p style=\"position:absolute;right:144px;bottom:64px;width:300px;font-family:'IBM Plex Mono', 'Courier New', monospace;font-size:24px;color:#6F6C64;text-align:right\">31 / 31</p>\n\n</section>"}]}};
